fn run_run_command(args: &[String]) -> i32 {
    match args.first().map(String::as_str) {
        Some("--help") | Some("-h") => {
            print_run_help();
            0
        }
        Some("first-zone") => run_first_zone_command(&args[1..]),
        Some("node-state-projection") => run_node_state_projection_command(&args[1..]),
        Some("plant-state-projection") => run_plant_state_projection_command(&args[1..]),
        Some(_) => run_arbitrary_run_command(args),
        None => {
            eprintln!("missing run command");
            print_run_help();
            RunExitCode::Args.code()
        }
    }
}

fn print_run_help() {
    eprintln!("{ARBITRARY_RUN_USAGE}");
    eprintln!("usage: eplus-rs run first-zone <input.epJSON> <weather.epw> [--hours N]");
    eprintln!("usage: eplus-rs run node-state-projection <input.epJSON> <output-dir> [--hours N]");
    eprintln!("usage: eplus-rs run plant-state-projection <input.epJSON> <output-dir> [--hours N]");
}

#[derive(Debug, Eq, PartialEq)]
struct ArbitraryRunParseError {
    message: String,
    show_usage: bool,
}

impl ArbitraryRunParseError {
    fn new(message: impl Into<String>, show_usage: bool) -> Self {
        Self {
            message: message.into(),
            show_usage,
        }
    }
}

fn parse_arbitrary_run_config(args: &[String]) -> Result<RunConfig, ArbitraryRunParseError> {
    let Some(input_path) = args.first() else {
        return Err(ArbitraryRunParseError::new("missing input path", true));
    };

    let mut weather_path = None;
    let mut output_dir = None;
    let mut mode = RunMode::Compatibility;
    let mut partial_policy = PartialRunPolicy::Deny;
    let mut output_format = RunOutputFormat::RustNative;
    let mut overwrite = false;
    let mut keep_intermediate = false;
    let mut trace_level = TraceLevel::Normal;
    let mut trace_selection = TraceSelection::default();
    let mut fail_on_warning = false;
    let mut dry_run = false;
    let mut oracle_baseline = false;
    let mut compare_oracle = false;
    let mut json_stdout = false;
    let mut oracle_root = None;
    let mut hours = None;

    let mut index = 1;
    while index < args.len() {
        match args[index].as_str() {
            "--weather" | "-w" => {
                let Some(value) = args.get(index + 1) else {
                    return Err(ArbitraryRunParseError::new(
                        format!("missing value for {}", args[index]),
                        true,
                    ));
                };
                weather_path = Some(PathBuf::from(value));
                index += 2;
            }
            "--output-dir" | "-d" => {
                let Some(value) = args.get(index + 1) else {
                    return Err(ArbitraryRunParseError::new(
                        format!("missing value for {}", args[index]),
                        true,
                    ));
                };
                output_dir = Some(PathBuf::from(value));
                index += 2;
            }
            "--mode" => {
                let Some(value) = args.get(index + 1) else {
                    return Err(ArbitraryRunParseError::new(
                        "missing value for --mode",
                        false,
                    ));
                };
                let Some(parsed) = RunMode::parse(value) else {
                    return Err(ArbitraryRunParseError::new(
                        format!("unsupported run mode: {value}"),
                        false,
                    ));
                };
                mode = parsed;
                index += 2;
            }
            "--partial" | "--partial-run" => {
                let Some(value) = args.get(index + 1) else {
                    return Err(ArbitraryRunParseError::new(
                        format!("missing value for {}", args[index]),
                        true,
                    ));
                };
                let Some(parsed) = PartialRunPolicy::parse(value) else {
                    return Err(ArbitraryRunParseError::new(
                        format!("unsupported partial run policy: {value}"),
                        false,
                    ));
                };
                partial_policy = parsed;
                index += 2;
            }
            "--allow-partial" => {
                partial_policy = PartialRunPolicy::Allow;
                index += 1;
            }
            "--deny-partial" => {
                partial_policy = PartialRunPolicy::Deny;
                index += 1;
            }
            "--format" | "--output-format" => {
                let Some(value) = args.get(index + 1) else {
                    return Err(ArbitraryRunParseError::new(
                        format!("missing value for {}", args[index]),
                        false,
                    ));
                };
                let Some(parsed) = RunOutputFormat::parse(value) else {
                    return Err(ArbitraryRunParseError::new(
                        format!("unsupported output format: {value}"),
                        false,
                    ));
                };
                output_format = parsed;
                index += 2;
            }
            "--overwrite" => {
                overwrite = true;
                index += 1;
            }
            "--keep-intermediate" => {
                keep_intermediate = true;
                index += 1;
            }
            "--trace-level" => {
                let Some(value) = args.get(index + 1) else {
                    return Err(ArbitraryRunParseError::new(
                        "missing value for --trace-level",
                        false,
                    ));
                };
                let Some(parsed) = TraceLevel::parse(value) else {
                    return Err(ArbitraryRunParseError::new(
                        format!("unsupported trace level: {value}"),
                        false,
                    ));
                };
                trace_level = parsed;
                index += 2;
            }
            "--trace-surface" => {
                let Some(value) = args.get(index + 1) else {
                    return Err(ArbitraryRunParseError::new(
                        "missing value for --trace-surface",
                        false,
                    ));
                };
                trace_selection.push_surface(value);
                index += 2;
            }
            "--trace-node" => {
                let Some(value) = args.get(index + 1) else {
                    return Err(ArbitraryRunParseError::new(
                        "missing value for --trace-node",
                        false,
                    ));
                };
                trace_selection.push_node(value);
                index += 2;
            }
            "--fail-on-warning" => {
                fail_on_warning = true;
                index += 1;
            }
            "--json" => {
                json_stdout = true;
                index += 1;
            }
            "--dry-run" => {
                dry_run = true;
                index += 1;
            }
            "--oracle-baseline" => {
                oracle_baseline = true;
                index += 1;
            }
            "--compare-oracle" => {
                compare_oracle = true;
                oracle_baseline = true;
                output_format = RunOutputFormat::Both;
                index += 1;
            }
            "--oracle-root" => {
                let Some(value) = args.get(index + 1) else {
                    return Err(ArbitraryRunParseError::new(
                        "missing value for --oracle-root",
                        false,
                    ));
                };
                oracle_root = Some(PathBuf::from(value));
                index += 2;
            }
            "--hours" => {
                let Some(value) = args.get(index + 1) else {
                    return Err(ArbitraryRunParseError::new(
                        "missing value for --hours",
                        false,
                    ));
                };
                let Ok(parsed) = value.parse::<usize>() else {
                    return Err(ArbitraryRunParseError::new(
                        format!("invalid --hours value: {value}"),
                        false,
                    ));
                };
                hours = Some(parsed);
                index += 2;
            }
            unknown => {
                return Err(ArbitraryRunParseError::new(
                    format!("unsupported run option: {unknown}"),
                    true,
                ));
            }
        }
    }

    let Some(output_dir) = output_dir else {
        return Err(ArbitraryRunParseError::new(
            "missing output directory",
            true,
        ));
    };

    Ok(RunConfig {
        input_path: PathBuf::from(input_path),
        weather_path,
        output_dir,
        mode,
        partial_policy,
        output_format,
        overwrite,
        keep_intermediate,
        trace_level,
        trace_selection,
        fail_on_warning,
        dry_run,
        oracle_baseline,
        compare_oracle,
        json_stdout,
        oracle_root,
        hours,
    })
}

fn run_arbitrary_run_command(args: &[String]) -> i32 {
    let config = match parse_arbitrary_run_config(args) {
        Ok(config) => config,
        Err(error) => {
            eprintln!("{}", error.message);
            if error.show_usage {
                eprintln!("{ARBITRARY_RUN_USAGE}");
            }
            return RunExitCode::Args.code();
        }
    };

    match run_arbitrary_idf(&config) {
        Ok(outcome) => {
            if config.json_stdout {
                match std::fs::read_to_string(&outcome.run_summary_path) {
                    Ok(summary) => print!("{summary}"),
                    Err(error) => eprintln!(
                        "failed to read run summary {}: {error}",
                        outcome.run_summary_path.display()
                    ),
                }
            } else {
                println!("Arbitrary Run");
                println!("  status: {}", outcome.exit_code.id());
                println!("  support_status: {}", outcome.support_status.id());
                println!("  run_result_state: {}", outcome.run_result_state.id());
                println!("  output_dir: {}", outcome.output_dir.display());
                println!("  run_summary: {}", outcome.run_summary_path.display());
                println!(
                    "  diagnostics: {}",
                    outcome.output_dir.join("diagnostics.json").display()
                );
                println!(
                    "  support_report: {}",
                    outcome.output_dir.join("support-report.md").display()
                );
            }
            outcome.exit_code.code()
        }
        Err(error) => {
            eprintln!("{error}");
            error.exit_code.code()
        }
    }
}

fn run_first_zone_command(args: &[String]) -> i32 {
    let Some(input_path) = args.first() else {
        eprintln!("missing input path");
        eprintln!("usage: eplus-rs run first-zone <input.epJSON> <weather.epw> [--hours N]");
        return 2;
    };
    let Some(weather_path) = args.get(1) else {
        eprintln!("missing weather path");
        eprintln!("usage: eplus-rs run first-zone <input.epJSON> <weather.epw> [--hours N]");
        return 2;
    };
    let hours = match parse_hours_arg(&args[2..], 24) {
        Ok(hours) => hours,
        Err(error) => {
            eprintln!("{error}");
            eprintln!("usage: eplus-rs run first-zone <input.epJSON> <weather.epw> [--hours N]");
            return 2;
        }
    };

    let raw_model = match load_epjson_file(input_path) {
        Ok(model) => model,
        Err(error) => {
            eprintln!("{error}");
            return 1;
        }
    };
    let result = compile_raw_model(&raw_model);
    let Some(model) = result.model else {
        print_compile_diagnostics(&result.report);
        return 1;
    };
    let weather_values = match load_epw_dry_bulb_series(weather_path) {
        Ok(values) => values,
        Err(error) => {
            eprintln!("{error}");
            return 1;
        }
    };
    let simulation_model = SimulationModel::from_typed(model);
    let simulation = match simulate_first_zone_uncontrolled(
        &simulation_model,
        &weather_values,
        FirstZoneSimulationOptions::hourly_samples(hours),
    ) {
        Ok(simulation) => simulation,
        Err(error) => {
            eprintln!("{error}");
            return 1;
        }
    };
    let Some(zone_series) = simulation
        .results
        .find_series(&simulation.summary.zone_name, "Zone Mean Air Temperature")
    else {
        eprintln!("first-zone simulation did not write zone temperature output");
        return 1;
    };
    let first_zone_temp_c = zone_series.values.first().copied().unwrap_or(0.0);
    let last_zone_temp_c = zone_series.values.last().copied().unwrap_or(0.0);

    println!("First Zone Runtime Diagnostic");
    println!("  runtime_class: diagnostic-toy");
    println!("  conformance_claim: false");
    println!("  algorithm_parity: false");
    println!("  zone: {}", simulation.summary.zone_name);
    println!("  samples: {}", simulation.summary.samples);
    println!("  result_series: {}", simulation.results.series.len());
    println!("  volume_m3: {:.6}", simulation.summary.volume_m3);
    println!(
        "  exterior_area_m2: {:.6}",
        simulation.summary.exterior_area_m2
    );
    println!(
        "  conductance_w_per_k: {:.6}",
        simulation.summary.conductance_w_per_k
    );
    println!(
        "  internal_gain_w: {:.6}",
        simulation.summary.internal_gain_w
    );
    println!("  first_zone_temp_c: {first_zone_temp_c:.6}");
    println!("  last_zone_temp_c: {last_zone_temp_c:.6}");
    println!("  status: extracted");

    0
}

fn run_node_state_projection_command(args: &[String]) -> i32 {
    let Some(input_path) = args.first() else {
        eprintln!("missing input path");
        eprintln!(
            "usage: eplus-rs run node-state-projection <input.epJSON> <output-dir> [--hours N]"
        );
        return 2;
    };
    let Some(output_dir) = args.get(1) else {
        eprintln!("missing output directory");
        eprintln!(
            "usage: eplus-rs run node-state-projection <input.epJSON> <output-dir> [--hours N]"
        );
        return 2;
    };
    let hours = match parse_hours_arg(&args[2..], 24) {
        Ok(hours) => hours,
        Err(error) => {
            eprintln!("{error}");
            eprintln!(
                "usage: eplus-rs run node-state-projection <input.epJSON> <output-dir> [--hours N]"
            );
            return 2;
        }
    };

    let raw_model = match load_epjson_file(input_path) {
        Ok(model) => model,
        Err(error) => {
            eprintln!("{error}");
            return 1;
        }
    };
    let result = compile_raw_model(&raw_model);
    let Some(model) = result.model else {
        print_compile_diagnostics(&result.report);
        return 1;
    };
    let simulation_model = SimulationModel::from_typed(model);
    let projection = match simulate_ideal_loads_node_state_projection(
        &simulation_model,
        NodeStateProjectionOptions::hourly_samples(hours),
    ) {
        Ok(projection) => projection,
        Err(error) => {
            eprintln!("{error}");
            return 1;
        }
    };
    let output_dir = Path::new(output_dir);
    if let Err(error) = write_node_state_projection_artifacts(output_dir, &projection) {
        eprintln!("{error}");
        return 1;
    }

    println!("Node State Projection");
    println!("  runtime_class: ideal-loads-node-state-projection");
    println!("  comparison_class: diagnostic-only");
    println!("  conformance_claim: false");
    println!("  algorithm_parity: false");
    println!("  tolerance_policy: none");
    println!("  nodes: {}", projection.summary.node_count);
    println!("  state_nodes: {}", projection.summary.state_node_count);
    println!("  samples: {}", projection.summary.samples);
    println!("  series: {}", projection.summary.series_count);
    println!(
        "  summary_json: {}",
        output_dir.join("node-state-summary.json").display()
    );
    println!("  status: projected");

    0
}

