fn run_compare_schedule_value(args: &[String]) -> i32 {
    let Some(input_path) = args.first() else {
        eprintln!("missing input path");
        eprintln!("usage: eplus-rs compare schedule-value <input.epJSON> <eplusout.eso>");
        return 2;
    };
    let Some(eso_path) = args.get(1) else {
        eprintln!("missing eplusout.eso path");
        eprintln!("usage: eplus-rs compare schedule-value <input.epJSON> <eplusout.eso>");
        return 2;
    };

    let raw_model = match load_epjson_file(input_path) {
        Ok(model) => model,
        Err(error) => {
            eprintln!("{error}");
            return 1;
        }
    };
    let result = compile_raw_model(&raw_model);
    let Some(model) = result.model.as_ref() else {
        print_compile_diagnostics(&result.report);
        return 1;
    };

    if model.schedules.is_empty() {
        eprintln!("no Schedule:Constant objects are available for comparison");
        return 1;
    }

    let mut oracle_series = Vec::new();
    for schedule in &model.schedules {
        let values = match load_eso_series(eso_path, &schedule.name.0, "Schedule Value") {
            Ok(values) => values,
            Err(error) => {
                eprintln!("{error}");
                return 1;
            }
        };
        oracle_series.push((schedule.id, schedule.name.0.clone(), values));
    }

    let sample_count = oracle_series
        .iter()
        .map(|(_id, _name, values)| values.len())
        .max()
        .unwrap_or(0);
    let schedule_cache = precompute_constant_schedule_cache(model, sample_count);
    let mut passed = true;

    println!("Schedule Value Comparison");
    println!("  comparison_class: smoke");
    println!("  conformance_claim: false");
    println!("  tolerance_policy: default");
    println!("  schedules: {}", oracle_series.len());
    for (schedule_id, schedule_name, expected_values) in oracle_series {
        let Some(trace) = schedule_cache.get(schedule_id) else {
            eprintln!("missing Rust schedule trace: {schedule_name}");
            return 1;
        };
        let observed_values = trace
            .values()
            .take(expected_values.len())
            .collect::<Vec<_>>();
        let comparison = compare_series(&expected_values, &observed_values, Tolerance::default());
        if !comparison.passed {
            passed = false;
        }
        println!(
            "  schedule: {} samples: {} max_abs_delta: {} status: {}",
            schedule_name,
            comparison.samples,
            comparison.max_abs_delta,
            if comparison.passed { "pass" } else { "fail" }
        );
        print_first_divergence("  ", comparison.first_divergence);
    }
    println!("  status: {}", if passed { "pass" } else { "fail" });

    if passed { 0 } else { 1 }
}

fn run_compare_geometry(args: &[String]) -> i32 {
    let Some(input_path) = args.first() else {
        eprintln!("missing input path");
        eprintln!("usage: eplus-rs compare geometry <input.epJSON> <eplusout.eio>");
        return 2;
    };
    let Some(eio_path) = args.get(1) else {
        eprintln!("missing eplusout.eio path");
        eprintln!("usage: eplus-rs compare geometry <input.epJSON> <eplusout.eio>");
        return 2;
    };

    let raw_model = match load_epjson_file(input_path) {
        Ok(model) => model,
        Err(error) => {
            eprintln!("{error}");
            return 1;
        }
    };
    let result = compile_raw_model(&raw_model);
    let Some(model) = result.model else {
        print_compile_diagnostics(&result.report);
        return 1;
    };
    let rust_zones = zone_geometry_summaries(&model);
    if rust_zones.is_empty() {
        eprintln!("no Zone objects are available for geometry comparison");
        return 1;
    }

    let oracle_zones = match load_eio_zone_geometry(eio_path) {
        Ok(zones) => zones,
        Err(error) => {
            eprintln!("{error}");
            return 1;
        }
    };

    let tolerance = Tolerance {
        absolute: 0.02,
        relative: 1.0e-6,
    };
    let mut passed = rust_zones.len() == oracle_zones.len();
    let mut first_divergence = None;
    if rust_zones.len() != oracle_zones.len() {
        first_divergence = Some(format!(
            "zone_count expected {} observed {}",
            oracle_zones.len(),
            rust_zones.len()
        ));
    }

    println!("Geometry Comparison");
    println!("  comparison_class: smoke");
    println!("  conformance_claim: false");
    println!("  tolerance_policy: absolute-0.02");
    println!("  zones: {}", rust_zones.len());
    println!("  oracle_zones: {}", oracle_zones.len());
    for rust_zone in &rust_zones {
        let Some(oracle_zone) = oracle_zones
            .iter()
            .find(|zone| zone.zone_name.eq_ignore_ascii_case(&rust_zone.zone_name))
        else {
            passed = false;
            record_first_divergence(
                &mut first_divergence,
                format!("zone {} missing_in_eio", rust_zone.zone_name),
            );
            println!("  zone: {} status: fail", rust_zone.zone_name);
            continue;
        };

        let surface_pass = oracle_zone.surface_count == rust_zone.surface_count;
        let floor_area_pass = tolerance.accepts(oracle_zone.floor_area_m2, rust_zone.floor_area_m2);
        let volume_pass = rust_zone
            .volume_m3
            .is_some_and(|volume_m3| tolerance.accepts(oracle_zone.volume_m3, volume_m3));
        let exterior_wall_area_pass = tolerance.accepts(
            oracle_zone.exterior_gross_wall_area_m2,
            rust_zone.exterior_wall_area_m2,
        );
        let zone_pass = surface_pass && floor_area_pass && volume_pass && exterior_wall_area_pass;
        if !zone_pass {
            passed = false;
            record_geometry_field_divergence(
                &mut first_divergence,
                rust_zone,
                oracle_zone,
                tolerance,
            );
        }

        let rust_volume = rust_zone
            .volume_m3
            .map(|volume_m3| format!("{volume_m3:.6}"))
            .unwrap_or_else(|| "unavailable".to_string());
        println!(
            "  zone: {} surfaces: {}/{} floor_area_m2: {:.6}/{:.6} volume_m3: {:.6}/{} exterior_wall_area_m2: {:.6}/{:.6} status: {}",
            rust_zone.zone_name,
            oracle_zone.surface_count,
            rust_zone.surface_count,
            oracle_zone.floor_area_m2,
            rust_zone.floor_area_m2,
            oracle_zone.volume_m3,
            rust_volume,
            oracle_zone.exterior_gross_wall_area_m2,
            rust_zone.exterior_wall_area_m2,
            if zone_pass { "pass" } else { "fail" }
        );
    }

    println!(
        "  first_divergence: {}",
        first_divergence.unwrap_or_else(|| "none".to_string())
    );
    println!("  status: {}", if passed { "pass" } else { "fail" });

    if passed { 0 } else { 1 }
}

fn run_compare_surface_geometry(args: &[String]) -> i32 {
    let Some(input_path) = args.first() else {
        eprintln!("missing input path");
        eprintln!("usage: eplus-rs compare surface-geometry <input.epJSON> <eplusout.eio>");
        return 2;
    };
    let Some(eio_path) = args.get(1) else {
        eprintln!("missing eplusout.eio path");
        eprintln!("usage: eplus-rs compare surface-geometry <input.epJSON> <eplusout.eio>");
        return 2;
    };

    let raw_model = match load_epjson_file(input_path) {
        Ok(model) => model,
        Err(error) => {
            eprintln!("{error}");
            return 1;
        }
    };
    let result = compile_raw_model(&raw_model);
    let Some(model) = result.model else {
        print_compile_diagnostics(&result.report);
        return 1;
    };
    let rust_surfaces = surface_geometry_summaries(&model);
    if rust_surfaces.is_empty() {
        eprintln!(
            "no BuildingSurface:Detailed objects are available for surface geometry comparison"
        );
        return 1;
    }

    let oracle_surfaces = match load_eio_heat_transfer_surfaces(eio_path) {
        Ok(surfaces) => surfaces,
        Err(error) => {
            eprintln!("{error}");
            return 1;
        }
    };
    let oracle_rules = match load_eio_surface_geometry_rules(eio_path) {
        Ok(rules) => rules,
        Err(error) => {
            eprintln!("{error}");
            return 1;
        }
    };
    let rust_rules = model.global_geometry_rules.unwrap_or_default();

    let tolerance = Tolerance {
        absolute: 0.01,
        relative: 1.0e-6,
    };
    let rules_pass = surface_geometry_rules_match(rust_rules, &oracle_rules);
    let mut passed = rust_surfaces.len() == oracle_surfaces.len() && rules_pass;
    let mut first_divergence = None;
    if !rules_pass {
        first_divergence = Some(format!(
            "surface_geometry_rules expected {}/{}/{}/{}/{} observed {}/{}/{}/{}/{}",
            oracle_rules.starting_corner,
            oracle_rules.vertex_input_direction,
            oracle_rules.coordinate_system,
            oracle_rules.daylight_reference_point_coordinate_system,
            oracle_rules.rectangular_surface_coordinate_system,
            starting_vertex_position_label(rust_rules.starting_vertex_position),
            vertex_entry_direction_label(rust_rules.vertex_entry_direction),
            geometry_coordinate_system_label(rust_rules.coordinate_system),
            geometry_coordinate_system_label(
                rust_rules.daylighting_reference_point_coordinate_system
            ),
            rectangular_geometry_coordinate_system_label(
                rust_rules.rectangular_surface_coordinate_system
            )
        ));
    } else if rust_surfaces.len() != oracle_surfaces.len() {
        first_divergence = Some(format!(
            "surface_count expected {} observed {}",
            oracle_surfaces.len(),
            rust_surfaces.len()
        ));
    }

    println!("Surface Geometry Comparison");
    println!("  comparison_class: smoke");
    println!("  conformance_claim: false");
    println!("  tolerance_policy: absolute-0.01-relative-0.000001");
    println!("  surfaces: {}", rust_surfaces.len());
    println!("  oracle_surfaces: {}", oracle_surfaces.len());
    println!(
        "  rules: starting_corner: {}/{} vertex_direction: {}/{} coordinate_system: {}/{} daylight_coordinate_system: {}/{} rectangular_coordinate_system: {}/{} status: {}",
        oracle_rules.starting_corner,
        starting_vertex_position_label(rust_rules.starting_vertex_position),
        oracle_rules.vertex_input_direction,
        vertex_entry_direction_label(rust_rules.vertex_entry_direction),
        oracle_rules.coordinate_system,
        geometry_coordinate_system_label(rust_rules.coordinate_system),
        oracle_rules.daylight_reference_point_coordinate_system,
        geometry_coordinate_system_label(rust_rules.daylighting_reference_point_coordinate_system),
        oracle_rules.rectangular_surface_coordinate_system,
        rectangular_geometry_coordinate_system_label(
            rust_rules.rectangular_surface_coordinate_system
        ),
        if rules_pass { "pass" } else { "fail" }
    );
    for rust_surface in &rust_surfaces {
        let Some(rust_vertices) = model
            .surfaces
            .iter()
            .find(|surface| surface.id == rust_surface.surface_id)
            .map(|surface| surface.vertices.as_slice())
        else {
            passed = false;
            record_first_divergence(
                &mut first_divergence,
                format!(
                    "surface {} missing_typed_vertices",
                    rust_surface.surface_name
                ),
            );
            println!("  surface: {} status: fail", rust_surface.surface_name);
            continue;
        };
        let Some(oracle_surface) = oracle_surfaces.iter().find(|surface| {
            surface
                .surface_name
                .eq_ignore_ascii_case(&rust_surface.surface_name)
        }) else {
            passed = false;
            record_first_divergence(
                &mut first_divergence,
                format!("surface {} missing_in_eio", rust_surface.surface_name),
            );
            println!("  surface: {} status: fail", rust_surface.surface_name);
            continue;
        };

        let surface_pass =
            surface_geometry_row_matches(rust_surface, rust_vertices, oracle_surface, tolerance);
        if !surface_pass {
            passed = false;
            record_surface_geometry_field_divergence(
                &mut first_divergence,
                rust_surface,
                rust_vertices,
                oracle_surface,
                tolerance,
            );
        }
        let vertex_status = match &oracle_surface.world_vertices {
            None => "not-requested",
            Some(vertices) if surface_world_vertices_match(vertices, rust_vertices, tolerance) => {
                "pass"
            }
            Some(_) => "fail",
        };

        println!(
            "  surface: {} class: {}/{} area_net_m2: {:.6}/{:.6} area_gross_m2: {:.6}/{:.6} azimuth_deg: {:.6}/{:.6} tilt_deg: {:.6}/{:.6} sides: {}/{} world_vertices: {} zone: {} status: {}",
            rust_surface.surface_name,
            oracle_surface.surface_class,
            surface_type_label(rust_surface.surface_type),
            oracle_surface.area_net_m2,
            rust_surface.area_m2,
            oracle_surface.area_gross_m2,
            rust_surface.area_m2,
            oracle_surface.azimuth_deg,
            rust_surface.azimuth_deg,
            oracle_surface.tilt_deg,
            rust_surface.tilt_deg,
            oracle_surface.side_count,
            rust_vertices.len(),
            vertex_status,
            rust_surface.zone_name,
            if surface_pass { "pass" } else { "fail" }
        );
    }

    println!(
        "  first_divergence: {}",
        first_divergence.unwrap_or_else(|| "none".to_string())
    );
    println!("  status: {}", if passed { "pass" } else { "fail" });

    if passed { 0 } else { 1 }
}

fn run_compare_construction_materials(args: &[String]) -> i32 {
    let Some(input_path) = args.first() else {
        eprintln!("missing input path");
        eprintln!("usage: eplus-rs compare construction-materials <input.epJSON> <eplusout.eio>");
        return 2;
    };
    let Some(eio_path) = args.get(1) else {
        eprintln!("missing eplusout.eio path");
        eprintln!("usage: eplus-rs compare construction-materials <input.epJSON> <eplusout.eio>");
        return 2;
    };

    let raw_model = match load_epjson_file(input_path) {
        Ok(model) => model,
        Err(error) => {
            eprintln!("{error}");
            return 1;
        }
    };
    let result = compile_raw_model(&raw_model);
    let Some(model) = result.model else {
        print_compile_diagnostics(&result.report);
        return 1;
    };
    let rust_rows = match construction_material_rows(&model) {
        Ok(rows) => rows,
        Err(error) => {
            eprintln!("{error}");
            return 1;
        }
    };
    if rust_rows.is_empty() {
        eprintln!(
            "no opaque Construction objects are available for construction/material comparison"
        );
        return 1;
    }

    let oracle_summaries = match load_eio_construction_material_summaries(eio_path) {
        Ok(summaries) => summaries,
        Err(error) => {
            eprintln!("{error}");
            return 1;
        }
    };

    let rust_material_count = construction_layer_material_count(&model);
    let oracle_material_count = oracle_summaries
        .iter()
        .map(|summary| summary.layers.len())
        .sum::<usize>();
    let tolerance = Tolerance {
        absolute: 0.001,
        relative: 1.0e-6,
    };
    let mut passed =
        rust_rows.len() == oracle_summaries.len() && rust_material_count == oracle_material_count;
    let mut first_divergence = None;
    if rust_rows.len() != oracle_summaries.len() {
        first_divergence = Some(format!(
            "construction_count expected {} observed {}",
            oracle_summaries.len(),
            rust_rows.len()
        ));
    } else if rust_material_count != oracle_material_count {
        first_divergence = Some(format!(
            "material_layer_count expected {oracle_material_count} observed {rust_material_count}"
        ));
    }

    println!("Construction Material Comparison");
    println!("  comparison_class: smoke");
    println!("  conformance_claim: false");
    println!("  tolerance_policy: absolute-0.001");
    println!("  constructions: {}", rust_rows.len());
    println!("  oracle_constructions: {}", oracle_summaries.len());
    println!("  materials: {}", rust_material_count);
    println!("  oracle_materials: {}", oracle_material_count);
    for rust_row in &rust_rows {
        let Some(oracle_summary) = oracle_summaries.iter().find(|summary| {
            summary
                .construction
                .construction_name
                .eq_ignore_ascii_case(&rust_row.construction_name)
        }) else {
            passed = false;
            record_first_divergence(
                &mut first_divergence,
                format!("construction {} missing_in_eio", rust_row.construction_name),
            );
            println!(
                "  construction: {} status: fail",
                rust_row.construction_name
            );
            continue;
        };
        let Some(oracle_outside_layer) = oracle_summary.layers.first() else {
            passed = false;
            record_first_divergence(
                &mut first_divergence,
                format!(
                    "construction {} has no EIO layers",
                    rust_row.construction_name
                ),
            );
            println!(
                "  construction: {} status: fail",
                rust_row.construction_name
            );
            continue;
        };
        let rust_outside_layer = match outside_construction_material_layer(rust_row) {
            Ok(layer) => layer,
            Err(error) => {
                passed = false;
                record_first_divergence(&mut first_divergence, error);
                println!(
                    "  construction: {} status: fail",
                    rust_row.construction_name
                );
                continue;
            }
        };

        let row_pass = construction_material_row_matches(rust_row, oracle_summary, tolerance);
        if !row_pass {
            passed = false;
            record_construction_material_field_divergence(
                &mut first_divergence,
                rust_row,
                oracle_summary,
                tolerance,
            );
        }

        println!(
            "  construction: {} declared_layers: {} oracle_layers: {} rust_layers: {} material: {}/{} thermal_conductance_w_per_m2_k: {:.6}/{:.6} material_resistance_m2_k_per_w: {:.6}/{:.6} status: {}",
            rust_row.construction_name,
            oracle_summary.construction.layer_count,
            oracle_summary.layers.len(),
            rust_row.layers.len(),
            oracle_outside_layer.material_name,
            rust_outside_layer.material_name,
            oracle_summary.construction.thermal_conductance_w_per_m2_k,
            rust_row.thermal_conductance_w_per_m2_k,
            oracle_outside_layer.thermal_resistance_m2_k_per_w,
            rust_outside_layer.material_thermal_resistance_m2_k_per_w,
            if row_pass { "pass" } else { "fail" }
        );
        for (layer_index, (oracle_layer, rust_layer)) in oracle_summary
            .layers
            .iter()
            .zip(&rust_row.layers)
            .enumerate()
        {
            println!(
                "    layer: {} material: {}/{} eio_format: {} thermal_resistance_m2_k_per_w: {:.6}/{:.6}",
                layer_index + 1,
                oracle_layer.material_name,
                rust_layer.material_name,
                eio_material_summary_format_label(oracle_layer.summary_format),
                oracle_layer.thermal_resistance_m2_k_per_w,
                rust_layer.material_thermal_resistance_m2_k_per_w
            );
        }
    }

    println!(
        "  first_divergence: {}",
        first_divergence.unwrap_or_else(|| "none".to_string())
    );
    println!("  status: {}", if passed { "pass" } else { "fail" });

    if passed { 0 } else { 1 }
}

fn run_compare_window_glazing_spectral_average(args: &[String]) -> i32 {
    const USAGE: &str =
        "usage: eplus-rs compare window-glazing-spectral-average <input.epJSON> <eplusout.eio>";
    let Some(input_path) = args.first() else {
        eprintln!("missing input path");
        eprintln!("{USAGE}");
        return 2;
    };
    let Some(eio_path) = args.get(1) else {
        eprintln!("missing eplusout.eio path");
        eprintln!("{USAGE}");
        return 2;
    };

    let raw_model = match load_epjson_file(input_path) {
        Ok(model) => model,
        Err(error) => {
            eprintln!("{error}");
            return 1;
        }
    };
    let result = compile_raw_model(&raw_model);
    let Some(model) = result.model else {
        print_compile_diagnostics(&result.report);
        return 1;
    };
    let rust_rows = match window_glazing_spectral_average_rows(&model) {
        Ok(rows) => rows,
        Err(error) => {
            eprintln!("{error}");
            return 1;
        }
    };
    if rust_rows.is_empty() {
        eprintln!(
            "no referenced WindowMaterial:Glazing SpectralAverage objects are available for comparison"
        );
        return 1;
    }
    let all_oracle_rows = match load_eio_window_material_glazing(eio_path) {
        Ok(rows) => rows,
        Err(error) => {
            eprintln!("{error}");
            return 1;
        }
    };
    let local_material_names = rust_rows
        .iter()
        .map(|row| row.material_name.as_str())
        .collect::<Vec<_>>();
    let oracle_rows =
        select_eio_window_material_glazing_occurrences(all_oracle_rows, &local_material_names);

    let tolerance = Tolerance {
        absolute: 0.00001,
        relative: 0.0,
    };
    let mut passed = rust_rows.len() == oracle_rows.len();
    let mut first_divergence = None;
    if !passed {
        first_divergence = Some(format!(
            "material_occurrence_count expected {} observed {}",
            oracle_rows.len(),
            rust_rows.len()
        ));
    }

    println!("Window Glazing SpectralAverage Comparison");
    println!("  comparison_class: smoke");
    println!("  conformance_claim: false");
    println!("  window_runtime_claim: false");
    println!("  tolerance_policy: absolute-0.00001");
    println!("  material_occurrences: {}", rust_rows.len());
    println!("  oracle_material_rows: {}", oracle_rows.len());

    for (rust_index, oracle_index) in
        window_glazing_spectral_average_pairings(&rust_rows, &oracle_rows)
    {
        let rust_row = &rust_rows[rust_index];
        let oracle_row = &oracle_rows[oracle_index];
        let row_pass = window_glazing_spectral_average_row_matches(rust_row, oracle_row, tolerance);
        if !row_pass {
            passed = false;
            record_window_glazing_spectral_average_divergence(
                &mut first_divergence,
                rust_row,
                oracle_row,
                tolerance,
                oracle_index,
            );
        }
        let rust_solar_diffusing = yes_no(rust_row.fields.solar_diffusing);
        let oracle_solar_diffusing = yes_no(oracle_row.solar_diffusing);
        println!(
            "  occurrence: {} rust_construction: {} material: {}/{} optical_data_type: {}/SpectralAverage spectral_data_set: {}/NONE thickness_m: {:.6}/{:.6} solar_t: {:.6}/{:.6} solar_rf: {:.6}/{:.6} solar_rb: {:.6}/{:.6} visible_t: {:.6}/{:.6} visible_rf: {:.6}/{:.6} visible_rb: {:.6}/{:.6} infrared_t: {:.6}/{:.6} infrared_ef: {:.6}/{:.6} infrared_eb: {:.6}/{:.6} conductivity_w_per_m_k: {:.6}/{:.6} dirt_factor: {:.6}/{:.6} solar_diffusing: {}/{} status: {}",
            oracle_index + 1,
            rust_row.construction_name,
            oracle_row.material_name,
            rust_row.material_name,
            oracle_row.optical_data_type,
            oracle_row
                .spectral_data_set_name
                .as_deref()
                .unwrap_or("NONE"),
            oracle_row.thickness_m,
            rust_row.fields.thickness_m,
            oracle_row.solar_transmittance,
            rust_row.fields.solar_transmittance_at_normal_incidence,
            oracle_row.front_solar_reflectance,
            rust_row
                .fields
                .front_side_solar_reflectance_at_normal_incidence,
            oracle_row.back_solar_reflectance,
            rust_row
                .fields
                .back_side_solar_reflectance_at_normal_incidence,
            oracle_row.visible_transmittance,
            rust_row.fields.visible_transmittance_at_normal_incidence,
            oracle_row.front_visible_reflectance,
            rust_row
                .fields
                .front_side_visible_reflectance_at_normal_incidence,
            oracle_row.back_visible_reflectance,
            rust_row
                .fields
                .back_side_visible_reflectance_at_normal_incidence,
            oracle_row.infrared_transmittance,
            rust_row.fields.infrared_transmittance_at_normal_incidence,
            oracle_row.front_thermal_emissivity,
            rust_row.fields.front_side_infrared_hemispherical_emissivity,
            oracle_row.back_thermal_emissivity,
            rust_row.fields.back_side_infrared_hemispherical_emissivity,
            oracle_row.conductivity_w_per_m_k,
            rust_row.fields.conductivity_w_per_m_k,
            oracle_row.dirt_factor,
            rust_row
                .fields
                .dirt_correction_factor_for_solar_and_visible_transmittance,
            oracle_solar_diffusing,
            rust_solar_diffusing,
            if row_pass { "pass" } else { "fail" },
        );
        println!(
            "    typed_only: material: {} youngs_modulus_pa: {:.6} poissons_ratio: {:.6}",
            rust_row.material_name,
            rust_row.fields.youngs_modulus_pa,
            rust_row.fields.poissons_ratio,
        );
    }

    println!(
        "  first_divergence: {}",
        first_divergence.unwrap_or_else(|| "none".to_string())
    );
    println!("  status: {}", if passed { "pass" } else { "fail" });
    if passed { 0 } else { 1 }
}

