fn heat_balance_ctf_component_first_samples(
    results: &ResultStore,
) -> Vec<HeatBalanceCtfComponentFirstSample> {
    let keys = results
        .series
        .iter()
        .filter(|series| {
            series
                .variable_name
                .eq_ignore_ascii_case(SURFACE_CTF_INSIDE_HISTORY_TERM_RATE_VARIABLE)
        })
        .map(|series| series.key.clone())
        .collect::<BTreeSet<_>>();

    keys.into_iter()
        .filter_map(|key| heat_balance_ctf_component_first_sample_for_key(results, &key))
        .collect()
}

fn heat_balance_ctf_component_first_sample_for_key(
    results: &ResultStore,
    key: &str,
) -> Option<HeatBalanceCtfComponentFirstSample> {
    Some(HeatBalanceCtfComponentFirstSample {
        key: key.to_string(),
        inside_conduction_rate_w: heat_balance_first_series_value(
            results,
            key,
            "Surface Inside Face Conduction Heat Transfer Rate",
        )?,
        inside_current_outside_term_w: heat_balance_first_series_value(
            results,
            key,
            SURFACE_CTF_INSIDE_CURRENT_OUTSIDE_TERM_RATE_VARIABLE,
        )?,
        inside_current_inside_term_w: heat_balance_first_series_value(
            results,
            key,
            SURFACE_CTF_INSIDE_CURRENT_INSIDE_TERM_RATE_VARIABLE,
        )?,
        inside_history_term_w: heat_balance_first_series_value(
            results,
            key,
            SURFACE_CTF_INSIDE_HISTORY_TERM_RATE_VARIABLE,
        )?,
        outside_conduction_rate_w: heat_balance_first_series_value(
            results,
            key,
            "Surface Outside Face Conduction Heat Transfer Rate",
        )?,
        outside_current_outside_term_w: heat_balance_first_series_value(
            results,
            key,
            SURFACE_CTF_OUTSIDE_CURRENT_OUTSIDE_TERM_RATE_VARIABLE,
        )?,
        outside_current_inside_term_w: heat_balance_first_series_value(
            results,
            key,
            SURFACE_CTF_OUTSIDE_CURRENT_INSIDE_TERM_RATE_VARIABLE,
        )?,
        outside_history_term_w: heat_balance_first_series_value(
            results,
            key,
            SURFACE_CTF_OUTSIDE_HISTORY_TERM_RATE_VARIABLE,
        )?,
        heat_storage_rate_w: heat_balance_first_series_value(
            results,
            key,
            "Surface Heat Storage Rate",
        )?,
    })
}

fn heat_balance_first_series_value(
    results: &ResultStore,
    key: &str,
    variable_name: &str,
) -> Option<f64> {
    results
        .find_series(key, variable_name)
        .and_then(|series| series.values.first().copied())
        .filter(|value| value.is_finite())
}

fn heat_balance_zone_air_coefficient_deltas(
    model: &SimulationModel,
    series: &[HeatBalanceSeriesDiagnostic],
) -> Vec<HeatBalanceZoneAirCoefficientDelta> {
    let zone_geometry = zone_geometry_summaries(&model.typed);
    model
        .typed
        .zones
        .iter()
        .filter_map(|zone| {
            let model_air_power_cap_w_per_k =
                heat_balance_zone_air_model_air_power_cap_w_per_k(model, &zone_geometry, zone)?;
            let mat = heat_balance_series(series, &zone.name.0, "Zone Mean Air Temperature")?;
            let internal_gain = heat_balance_series(
                series,
                &zone.name.0,
                "Zone Air Heat Balance Internal Convective Heat Gain Rate",
            )?;
            let air_storage = heat_balance_series(
                series,
                &zone.name.0,
                "Zone Air Heat Balance Air Energy Storage Rate",
            )?;
            let surface_convection = heat_balance_series(
                series,
                &zone.name.0,
                "Zone Air Heat Balance Surface Convection Rate",
            )?;
            let surfaces = model
                .typed
                .surfaces
                .iter()
                .filter(|surface| surface.zone == zone.id)
                .map(|surface| {
                    let area_m2 = surface_area_m2(&surface.vertices);
                    let inside_temperature = heat_balance_series(
                        series,
                        &surface.name.0,
                        "Surface Inside Face Temperature",
                    )?;
                    let inside_convection_coefficient = heat_balance_series(
                        series,
                        &surface.name.0,
                        "Surface Inside Face Convection Heat Transfer Coefficient",
                    )?;
                    let inside_convection = heat_balance_series(
                        series,
                        &surface.name.0,
                        "Surface Inside Face Convection Heat Gain Rate",
                    )?;
                    Some((
                        area_m2,
                        inside_temperature,
                        inside_convection_coefficient,
                        inside_convection,
                    ))
                })
                .collect::<Option<Vec<_>>>()?;
            if surfaces.is_empty() {
                return None;
            }

            let samples = [
                mat.samples,
                internal_gain.samples,
                air_storage.samples,
                surface_convection.samples,
            ]
            .into_iter()
            .chain(surfaces.iter().flat_map(
                |(_, inside_temperature, inside_convection_coefficient, inside_convection)| {
                    [
                        inside_temperature.samples,
                        inside_convection_coefficient.samples,
                        inside_convection.samples,
                    ]
                },
            ))
            .min()
            .unwrap_or(0);
            if samples == 0 {
                return None;
            }

            let mut oracle_sum_ha = Vec::with_capacity(samples);
            let mut rust_sum_ha = Vec::with_capacity(samples);
            let mut oracle_sum_hat_surf = Vec::with_capacity(samples);
            let mut rust_sum_hat_surf = Vec::with_capacity(samples);
            let mut oracle_sum_hat_ref = Vec::with_capacity(samples);
            let mut rust_sum_hat_ref = Vec::with_capacity(samples);
            let mut oracle_temp_dep = Vec::with_capacity(samples);
            let mut rust_temp_dep = Vec::with_capacity(samples);
            let mut oracle_temp_ind = Vec::with_capacity(samples);
            let mut rust_temp_ind = Vec::with_capacity(samples);
            let mut oracle_air_power_cap = Vec::with_capacity(samples);
            let mut rust_air_power_cap = Vec::with_capacity(samples);
            let mut oracle_temp_history = Vec::with_capacity(samples);
            let mut rust_temp_history = Vec::with_capacity(samples);

            for sample_index in 0..samples {
                let mut oracle_surface_sums = ZoneAirOutputCoefficientSums::default();
                let mut rust_surface_sums = ZoneAirOutputCoefficientSums::default();
                for (
                    area_m2,
                    inside_temperature,
                    inside_convection_coefficient,
                    inside_convection,
                ) in &surfaces
                {
                    oracle_surface_sums.add_surface(
                        *area_m2,
                        inside_convection_coefficient.sample_rows[sample_index].oracle_c,
                        inside_temperature.sample_rows[sample_index].oracle_c,
                        inside_convection.sample_rows[sample_index].oracle_c,
                    );
                    rust_surface_sums.add_surface(
                        *area_m2,
                        inside_convection_coefficient.sample_rows[sample_index].rust_c,
                        inside_temperature.sample_rows[sample_index].rust_c,
                        inside_convection.sample_rows[sample_index].rust_c,
                    );
                }

                let oracle_internal_gain = internal_gain.sample_rows[sample_index].oracle_c;
                let rust_internal_gain = internal_gain.sample_rows[sample_index].rust_c;

                oracle_sum_ha.push(oracle_surface_sums.sum_ha_w_per_k);
                rust_sum_ha.push(rust_surface_sums.sum_ha_w_per_k);
                oracle_sum_hat_surf.push(oracle_surface_sums.sum_hat_surf_w);
                rust_sum_hat_surf.push(rust_surface_sums.sum_hat_surf_w);
                oracle_sum_hat_ref.push(oracle_surface_sums.sum_hat_ref_w);
                rust_sum_hat_ref.push(rust_surface_sums.sum_hat_ref_w);
                oracle_temp_dep.push(oracle_surface_sums.sum_ha_w_per_k);
                rust_temp_dep.push(rust_surface_sums.sum_ha_w_per_k);
                oracle_temp_ind.push(
                    oracle_internal_gain + oracle_surface_sums.sum_hat_surf_w
                        - oracle_surface_sums.sum_hat_ref_w,
                );
                rust_temp_ind.push(
                    rust_internal_gain + rust_surface_sums.sum_hat_surf_w
                        - rust_surface_sums.sum_hat_ref_w,
                );
                oracle_air_power_cap.push(model_air_power_cap_w_per_k);
                rust_air_power_cap.push(model_air_power_cap_w_per_k);
                oracle_temp_history.push(inferred_third_order_history_term_w(
                    model_air_power_cap_w_per_k,
                    mat,
                    sample_index,
                    true,
                ));
                rust_temp_history.push(inferred_third_order_history_term_w(
                    model_air_power_cap_w_per_k,
                    mat,
                    sample_index,
                    false,
                ));
            }

            let mat_oracle = heat_balance_oracle_values(mat, samples);
            let mat_rust = heat_balance_rust_values(mat, samples);
            let air_storage_oracle = heat_balance_oracle_values(air_storage, samples);
            let air_storage_rust = heat_balance_rust_values(air_storage, samples);
            let surface_convection_oracle = heat_balance_oracle_values(surface_convection, samples);
            let surface_convection_rust = heat_balance_rust_values(surface_convection, samples);
            let first_divergence = first_zone_air_coefficient_divergence(
                &[
                    ("SumHA", &oracle_sum_ha, &rust_sum_ha),
                    ("SumHATsurf", &oracle_sum_hat_surf, &rust_sum_hat_surf),
                    ("SumHATref", &oracle_sum_hat_ref, &rust_sum_hat_ref),
                    ("TempDepCoef", &oracle_temp_dep, &rust_temp_dep),
                    ("TempIndCoef", &oracle_temp_ind, &rust_temp_ind),
                    ("AirPowerCap", &oracle_air_power_cap, &rust_air_power_cap),
                    ("TempHistoryTerm", &oracle_temp_history, &rust_temp_history),
                    ("MAT", &mat_oracle, &mat_rust),
                    ("AirStorage", &air_storage_oracle, &air_storage_rust),
                    (
                        "SurfaceConvection",
                        &surface_convection_oracle,
                        &surface_convection_rust,
                    ),
                ],
                samples,
            );

            Some(HeatBalanceZoneAirCoefficientDelta {
                key: zone.name.0.clone(),
                samples,
                first_divergence_source: first_divergence
                    .as_ref()
                    .map(|divergence| divergence.source.to_string())
                    .unwrap_or_else(|| "none".to_string()),
                first_divergence_sample_index: first_divergence
                    .as_ref()
                    .map(|divergence| divergence.sample_index),
                first_divergence_delta: first_divergence.as_ref().map_or(0.0, |d| d.delta),
                sum_ha_delta: delta_summary(&oracle_sum_ha, &rust_sum_ha),
                sum_hat_surf_delta: delta_summary(&oracle_sum_hat_surf, &rust_sum_hat_surf),
                sum_hat_ref_delta: delta_summary(&oracle_sum_hat_ref, &rust_sum_hat_ref),
                temp_dependent_coefficient_delta: delta_summary(&oracle_temp_dep, &rust_temp_dep),
                temp_independent_coefficient_delta: delta_summary(&oracle_temp_ind, &rust_temp_ind),
                air_power_cap_delta: delta_summary(&oracle_air_power_cap, &rust_air_power_cap),
                temp_history_term_delta: delta_summary(&oracle_temp_history, &rust_temp_history),
                mat_delta: delta_summary(&mat_oracle, &mat_rust),
                air_storage_delta: delta_summary(&air_storage_oracle, &air_storage_rust),
                surface_convection_delta: delta_summary(
                    &surface_convection_oracle,
                    &surface_convection_rust,
                ),
            })
        })
        .collect()
}

fn heat_balance_zone_air_surface_convection_closure_deltas(
    model: &SimulationModel,
    series: &[HeatBalanceSeriesDiagnostic],
) -> Vec<HeatBalanceZoneAirSurfaceConvectionClosureDelta> {
    model
        .typed
        .zones
        .iter()
        .filter_map(|zone| {
            let zone_surface_convection = heat_balance_series(
                series,
                &zone.name.0,
                "Zone Air Heat Balance Surface Convection Rate",
            )?;
            let surfaces = model
                .typed
                .surfaces
                .iter()
                .filter(|surface| surface.zone == zone.id)
                .filter_map(|surface| {
                    heat_balance_series(
                        series,
                        &surface.name.0,
                        "Surface Inside Face Convection Heat Gain Rate",
                    )
                })
                .collect::<Vec<_>>();
            if surfaces.is_empty() {
                return None;
            }

            let samples = surfaces
                .iter()
                .map(|surface| surface.samples)
                .chain(std::iter::once(zone_surface_convection.samples))
                .min()
                .unwrap_or(0);
            if samples == 0 {
                return None;
            }

            let mut oracle_zone_surface_convection = Vec::with_capacity(samples);
            let mut rust_zone_surface_convection = Vec::with_capacity(samples);
            let mut oracle_surface_report_sum = Vec::with_capacity(samples);
            let mut rust_surface_report_sum = Vec::with_capacity(samples);
            let mut oracle_closure_residual = Vec::with_capacity(samples);
            let mut rust_closure_residual = Vec::with_capacity(samples);
            let zero = vec![0.0; samples];

            for sample_index in 0..samples {
                let oracle_zone = zone_surface_convection.sample_rows[sample_index].oracle_c;
                let rust_zone = zone_surface_convection.sample_rows[sample_index].rust_c;
                let oracle_surface_sum = surfaces
                    .iter()
                    .map(|surface| surface.sample_rows[sample_index].oracle_c)
                    .sum::<f64>();
                let rust_surface_sum = surfaces
                    .iter()
                    .map(|surface| surface.sample_rows[sample_index].rust_c)
                    .sum::<f64>();
                oracle_zone_surface_convection.push(oracle_zone);
                rust_zone_surface_convection.push(rust_zone);
                oracle_surface_report_sum.push(oracle_surface_sum);
                rust_surface_report_sum.push(rust_surface_sum);
                oracle_closure_residual.push(oracle_zone + oracle_surface_sum);
                rust_closure_residual.push(rust_zone + rust_surface_sum);
            }

            Some(HeatBalanceZoneAirSurfaceConvectionClosureDelta {
                key: zone.name.0.clone(),
                surface_count: surfaces.len(),
                samples,
                zone_surface_convection_delta: delta_summary(
                    &oracle_zone_surface_convection,
                    &rust_zone_surface_convection,
                ),
                surface_report_sum_delta: delta_summary(
                    &oracle_surface_report_sum,
                    &rust_surface_report_sum,
                ),
                oracle_closure_residual: delta_summary(&zero, &oracle_closure_residual),
                rust_closure_residual: delta_summary(&zero, &rust_closure_residual),
                closure_residual_delta: delta_summary(
                    &oracle_closure_residual,
                    &rust_closure_residual,
                ),
            })
        })
        .collect()
}

fn heat_balance_zone_air_surface_coefficient_deltas(
    model: &SimulationModel,
    series: &[HeatBalanceSeriesDiagnostic],
) -> Vec<HeatBalanceZoneAirSurfaceCoefficientDelta> {
    model
        .typed
        .surfaces
        .iter()
        .filter_map(|surface| {
            let zone_key = model
                .typed
                .zones
                .iter()
                .find(|zone| zone.id == surface.zone)
                .map(|zone| zone.name.0.clone())?;
            let area_m2 = surface_area_m2(&surface.vertices);
            if area_m2 <= 0.0 {
                return None;
            }
            let inside_temperature =
                heat_balance_series(series, &surface.name.0, "Surface Inside Face Temperature")?;
            let inside_hconv = heat_balance_series(
                series,
                &surface.name.0,
                "Surface Inside Face Convection Heat Transfer Coefficient",
            )?;
            let inside_convection_gain = heat_balance_series(
                series,
                &surface.name.0,
                "Surface Inside Face Convection Heat Gain Rate",
            )?;
            let samples = [
                inside_temperature.samples,
                inside_hconv.samples,
                inside_convection_gain.samples,
            ]
            .into_iter()
            .min()
            .unwrap_or(0);
            if samples == 0 {
                return None;
            }

            let mut oracle_sum_ha = Vec::with_capacity(samples);
            let mut rust_sum_ha = Vec::with_capacity(samples);
            let mut oracle_sum_hat_surf = Vec::with_capacity(samples);
            let mut rust_sum_hat_surf = Vec::with_capacity(samples);
            let mut oracle_sum_hat_ref = Vec::with_capacity(samples);
            let mut rust_sum_hat_ref = Vec::with_capacity(samples);
            let mut oracle_reference_air_temperature = Vec::with_capacity(samples);
            let mut rust_reference_air_temperature = Vec::with_capacity(samples);
            let mut oracle_inside_temperature = Vec::with_capacity(samples);
            let mut rust_inside_temperature = Vec::with_capacity(samples);
            let mut oracle_inside_hconv = Vec::with_capacity(samples);
            let mut rust_inside_hconv = Vec::with_capacity(samples);
            let mut oracle_inside_convection_gain = Vec::with_capacity(samples);
            let mut rust_inside_convection_gain = Vec::with_capacity(samples);

            for sample_index in 0..samples {
                let oracle_hconv = inside_hconv.sample_rows[sample_index].oracle_c;
                let rust_hconv = inside_hconv.sample_rows[sample_index].rust_c;
                let oracle_surface_temperature =
                    inside_temperature.sample_rows[sample_index].oracle_c;
                let rust_surface_temperature = inside_temperature.sample_rows[sample_index].rust_c;
                let oracle_convection_gain =
                    inside_convection_gain.sample_rows[sample_index].oracle_c;
                let rust_convection_gain = inside_convection_gain.sample_rows[sample_index].rust_c;
                let oracle_ha = area_m2 * oracle_hconv;
                let rust_ha = area_m2 * rust_hconv;
                let oracle_hat_surf = oracle_ha * oracle_surface_temperature;
                let rust_hat_surf = rust_ha * rust_surface_temperature;

                oracle_sum_ha.push(oracle_ha);
                rust_sum_ha.push(rust_ha);
                oracle_sum_hat_surf.push(oracle_hat_surf);
                rust_sum_hat_surf.push(rust_hat_surf);
                oracle_sum_hat_ref.push(oracle_hat_surf + oracle_convection_gain);
                rust_sum_hat_ref.push(rust_hat_surf + rust_convection_gain);
                oracle_reference_air_temperature.push(
                    heat_balance_reference_air_temperature_from_convection_output(
                        area_m2,
                        oracle_hconv,
                        oracle_surface_temperature,
                        oracle_convection_gain,
                    ),
                );
                rust_reference_air_temperature.push(
                    heat_balance_reference_air_temperature_from_convection_output(
                        area_m2,
                        rust_hconv,
                        rust_surface_temperature,
                        rust_convection_gain,
                    ),
                );
                oracle_inside_temperature.push(oracle_surface_temperature);
                rust_inside_temperature.push(rust_surface_temperature);
                oracle_inside_hconv.push(oracle_hconv);
                rust_inside_hconv.push(rust_hconv);
                oracle_inside_convection_gain.push(oracle_convection_gain);
                rust_inside_convection_gain.push(rust_convection_gain);
            }

            Some(HeatBalanceZoneAirSurfaceCoefficientDelta {
                zone_key,
                key: surface.name.0.clone(),
                area_m2,
                samples,
                sum_ha_delta: delta_summary(&oracle_sum_ha, &rust_sum_ha),
                sum_hat_surf_delta: delta_summary(&oracle_sum_hat_surf, &rust_sum_hat_surf),
                sum_hat_ref_delta: delta_summary(&oracle_sum_hat_ref, &rust_sum_hat_ref),
                reference_air_temperature_delta: delta_summary(
                    &oracle_reference_air_temperature,
                    &rust_reference_air_temperature,
                ),
                inside_face_temperature_delta: delta_summary(
                    &oracle_inside_temperature,
                    &rust_inside_temperature,
                ),
                inside_hconv_delta: delta_summary(&oracle_inside_hconv, &rust_inside_hconv),
                inside_convection_gain_delta: delta_summary(
                    &oracle_inside_convection_gain,
                    &rust_inside_convection_gain,
                ),
            })
        })
        .collect()
}

fn heat_balance_reference_air_temperature_from_convection_output(
    area_m2: f64,
    hconv_w_per_m2_k: f64,
    inside_face_temperature_c: f64,
    convection_gain_w: f64,
) -> f64 {
    let ha_w_per_k = area_m2 * hconv_w_per_m2_k;
    if !ha_w_per_k.is_finite() || ha_w_per_k.abs() <= f64::EPSILON {
        inside_face_temperature_c
    } else {
        inside_face_temperature_c + convection_gain_w / ha_w_per_k
    }
}

fn heat_balance_oracle_values(series: &HeatBalanceSeriesDiagnostic, samples: usize) -> Vec<f64> {
    series
        .sample_rows
        .iter()
        .take(samples)
        .map(|point| point.oracle_c)
        .collect()
}

fn heat_balance_rust_values(series: &HeatBalanceSeriesDiagnostic, samples: usize) -> Vec<f64> {
    series
        .sample_rows
        .iter()
        .take(samples)
        .map(|point| point.rust_c)
        .collect()
}

#[derive(Clone, Copy, Debug, Default)]
struct ZoneAirOutputCoefficientSums {
    sum_ha_w_per_k: f64,
    sum_hat_surf_w: f64,
    sum_hat_ref_w: f64,
}

impl ZoneAirOutputCoefficientSums {
    fn add_surface(
        &mut self,
        area_m2: f64,
        hconv_w_per_m2_k: f64,
        inside_temperature_c: f64,
        surface_convection_gain_w: f64,
    ) {
        let ha_w_per_k = area_m2 * hconv_w_per_m2_k;
        if !ha_w_per_k.is_finite() || ha_w_per_k.abs() <= f64::EPSILON {
            return;
        }
        let reference_air_temperature_c =
            inside_temperature_c + surface_convection_gain_w / ha_w_per_k;
        self.sum_ha_w_per_k += ha_w_per_k;
        self.sum_hat_surf_w += ha_w_per_k * inside_temperature_c;
        self.sum_hat_ref_w += ha_w_per_k * reference_air_temperature_c;
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct ZoneAirCoefficientFirstDivergence<'a> {
    source: &'a str,
    sample_index: usize,
    delta: f64,
}

fn first_zone_air_coefficient_divergence<'a>(
    components: &[(&'a str, &[f64], &[f64])],
    samples: usize,
) -> Option<ZoneAirCoefficientFirstDivergence<'a>> {
    for sample_index in 0..samples {
        let mut best_source = None;
        let mut best_delta = 0.0_f64;
        for (source, oracle, rust) in components {
            let delta = (oracle[sample_index] - rust[sample_index]).abs();
            if delta.is_finite() && delta > best_delta {
                best_source = Some(*source);
                best_delta = delta;
            }
        }
        if let Some(source) = best_source.filter(|_| best_delta > 1.0e-9) {
            return Some(ZoneAirCoefficientFirstDivergence {
                source,
                sample_index,
                delta: best_delta,
            });
        }
    }
    None
}

fn heat_balance_zone_air_model_air_power_cap_w_per_k(
    model: &SimulationModel,
    zone_geometry: &[ZoneGeometrySummary],
    zone: &ep_model::Zone,
) -> Option<f64> {
    let volume_m3 = zone_geometry
        .iter()
        .find(|summary| summary.zone_id == zone.id)
        .and_then(|summary| summary.volume_m3)?;
    let zone_multiplier = f64::from(zone.multiplier.max(1));
    let zone_timesteps_per_hour = model.typed.timestep.number_of_timesteps_per_hour.max(1);
    let timestep_seconds = 3600.0 / f64::from(zone_timesteps_per_hour);
    if volume_m3 <= 0.0 || timestep_seconds <= 0.0 {
        return None;
    }
    energyplus_zone_air_heat_capacity_j_per_k(
        volume_m3 * zone_multiplier,
        ENERGYPLUS_STANDARD_ATMOSPHERIC_PRESSURE_PA,
        20.0,
        ENERGYPLUS_DEFAULT_ZONE_AIR_HUMIDITY_RATIO,
    )
    .map(|air_heat_capacity_j_per_k| air_heat_capacity_j_per_k / timestep_seconds)
}

fn inferred_third_order_history_term_w(
    air_power_cap_w_per_k: f64,
    mat: &HeatBalanceSeriesDiagnostic,
    sample_index: usize,
    oracle: bool,
) -> f64 {
    if sample_index < 3 {
        return 0.0;
    }
    let sample = |offset: usize| {
        let point = mat.sample_rows[sample_index - offset];
        if oracle { point.oracle_c } else { point.rust_c }
    };
    air_power_cap_w_per_k * (3.0 * sample(1) - 1.5 * sample(2) + (1.0 / 3.0) * sample(3))
}

fn heat_balance_ctf_history_first_sample_deltas(
    model: &SimulationModel,
    series: &[HeatBalanceSeriesDiagnostic],
    ctf_coefficients: &[ConstructionCtfCoefficientOverride],
    component_rows: &[HeatBalanceCtfComponentFirstSample],
) -> Vec<HeatBalanceCtfHistoryFirstSampleDelta> {
    model
        .typed
        .surfaces
        .iter()
        .filter_map(|surface| {
            let construction = model
                .typed
                .constructions
                .iter()
                .find(|construction| construction.id == surface.construction)?;
            let zero = ctf_coefficients.iter().find(|coefficient| {
                coefficient.time_index == 0
                    && coefficient
                        .construction_name
                        .eq_ignore_ascii_case(&construction.name.0)
            })?;
            let component = component_rows
                .iter()
                .find(|component| component.key.eq_ignore_ascii_case(&surface.name.0))?;
            let area_m2 = surface_area_m2(&surface.vertices);
            if area_m2 <= 0.0 {
                return None;
            }
            let oracle_inside_temperature_c = heat_balance_oracle_first_value(
                series,
                &surface.name.0,
                "Surface Inside Face Temperature",
            )?;
            let oracle_outside_temperature_c = heat_balance_oracle_first_value(
                series,
                &surface.name.0,
                "Surface Outside Face Temperature",
            )?;
            let rust_inside_temperature_c = heat_balance_rust_first_value(
                series,
                &surface.name.0,
                "Surface Inside Face Temperature",
            )?;
            let rust_outside_temperature_c = heat_balance_rust_first_value(
                series,
                &surface.name.0,
                "Surface Outside Face Temperature",
            )?;
            let oracle_inside_conduction_rate_w = heat_balance_oracle_first_value(
                series,
                &surface.name.0,
                "Surface Inside Face Conduction Heat Transfer Rate",
            )?;
            let oracle_outside_conduction_rate_w = heat_balance_oracle_first_value(
                series,
                &surface.name.0,
                "Surface Outside Face Conduction Heat Transfer Rate",
            )?;

            let oracle_inside_current_term_w = area_m2
                * (oracle_outside_temperature_c * zero.cross_w_per_m2_k
                    - oracle_inside_temperature_c * zero.inside_w_per_m2_k);
            let oracle_outside_current_term_w = -area_m2
                * (oracle_outside_temperature_c * zero.outside_w_per_m2_k
                    - oracle_inside_temperature_c * zero.cross_w_per_m2_k);
            let rust_inside_current_term_w =
                component.inside_current_outside_term_w + component.inside_current_inside_term_w;
            let rust_outside_current_term_w =
                component.outside_current_outside_term_w + component.outside_current_inside_term_w;
            let oracle_inside_history_term_w =
                oracle_inside_conduction_rate_w - oracle_inside_current_term_w;
            let oracle_outside_history_term_w =
                oracle_outside_conduction_rate_w - oracle_outside_current_term_w;

            Some(HeatBalanceCtfHistoryFirstSampleDelta {
                key: surface.name.0.clone(),
                construction_name: construction.name.0.clone(),
                area_m2,
                ctf_outside_0_w_per_m2_k: zero.outside_w_per_m2_k,
                ctf_cross_0_w_per_m2_k: zero.cross_w_per_m2_k,
                ctf_inside_0_w_per_m2_k: zero.inside_w_per_m2_k,
                oracle_outside_face_temperature_c: oracle_outside_temperature_c,
                rust_outside_face_temperature_c: rust_outside_temperature_c,
                outside_face_temperature_delta_c: (oracle_outside_temperature_c
                    - rust_outside_temperature_c)
                    .abs(),
                oracle_inside_face_temperature_c: oracle_inside_temperature_c,
                rust_inside_face_temperature_c: rust_inside_temperature_c,
                inside_face_temperature_delta_c: (oracle_inside_temperature_c
                    - rust_inside_temperature_c)
                    .abs(),
                oracle_inside_current_term_w,
                rust_inside_current_term_w,
                inside_current_delta_w: (oracle_inside_current_term_w - rust_inside_current_term_w)
                    .abs(),
                oracle_inside_history_term_w,
                rust_inside_history_term_w: component.inside_history_term_w,
                inside_history_delta_w: (oracle_inside_history_term_w
                    - component.inside_history_term_w)
                    .abs(),
                oracle_outside_current_term_w,
                rust_outside_current_term_w,
                outside_current_delta_w: (oracle_outside_current_term_w
                    - rust_outside_current_term_w)
                    .abs(),
                oracle_outside_history_term_w,
                rust_outside_history_term_w: component.outside_history_term_w,
                outside_history_delta_w: (oracle_outside_history_term_w
                    - component.outside_history_term_w)
                    .abs(),
            })
        })
        .collect()
}

fn heat_balance_ctf_history_series_deltas(
    model: &SimulationModel,
    series: &[HeatBalanceSeriesDiagnostic],
    ctf_coefficients: &[ConstructionCtfCoefficientOverride],
    results: &ResultStore,
) -> Vec<HeatBalanceCtfHistorySeriesDelta> {
    model
        .typed
        .surfaces
        .iter()
        .filter_map(|surface| {
            let construction = model
                .typed
                .constructions
                .iter()
                .find(|construction| construction.id == surface.construction)?;
            let zero = ctf_coefficients.iter().find(|coefficient| {
                coefficient.time_index == 0
                    && coefficient
                        .construction_name
                        .eq_ignore_ascii_case(&construction.name.0)
            })?;
            let area_m2 = surface_area_m2(&surface.vertices);
            if area_m2 <= 0.0 {
                return None;
            }

            let oracle_inside_temperatures = heat_balance_oracle_series_values(
                series,
                &surface.name.0,
                "Surface Inside Face Temperature",
            )?;
            let oracle_outside_temperatures = heat_balance_oracle_series_values(
                series,
                &surface.name.0,
                "Surface Outside Face Temperature",
            )?;
            let oracle_inside_conduction = heat_balance_oracle_series_values(
                series,
                &surface.name.0,
                "Surface Inside Face Conduction Heat Transfer Rate",
            )?;
            let oracle_outside_conduction = heat_balance_oracle_series_values(
                series,
                &surface.name.0,
                "Surface Outside Face Conduction Heat Transfer Rate",
            )?;
            let rust_inside_current_outside = heat_balance_result_series_values(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_CURRENT_OUTSIDE_TERM_RATE_VARIABLE,
            )?;
            let rust_inside_current_inside = heat_balance_result_series_values(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_CURRENT_INSIDE_TERM_RATE_VARIABLE,
            )?;
            let rust_inside_history = heat_balance_result_series_values(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_HISTORY_TERM_RATE_VARIABLE,
            )?;
            let rust_inside_history_temperature = heat_balance_result_series_values(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_HISTORY_TEMPERATURE_TERM_RATE_VARIABLE,
            )?;
            let rust_inside_history_flux = heat_balance_result_series_values(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_HISTORY_FLUX_TERM_RATE_VARIABLE,
            )?;
            let rust_outside_current_outside = heat_balance_result_series_values(
                results,
                &surface.name.0,
                SURFACE_CTF_OUTSIDE_CURRENT_OUTSIDE_TERM_RATE_VARIABLE,
            )?;
            let rust_outside_current_inside = heat_balance_result_series_values(
                results,
                &surface.name.0,
                SURFACE_CTF_OUTSIDE_CURRENT_INSIDE_TERM_RATE_VARIABLE,
            )?;
            let rust_outside_history = heat_balance_result_series_values(
                results,
                &surface.name.0,
                SURFACE_CTF_OUTSIDE_HISTORY_TERM_RATE_VARIABLE,
            )?;

            let samples = [
                oracle_inside_temperatures.len(),
                oracle_outside_temperatures.len(),
                oracle_inside_conduction.len(),
                oracle_outside_conduction.len(),
                rust_inside_current_outside.len(),
                rust_inside_current_inside.len(),
                rust_inside_history.len(),
                rust_inside_history_temperature.len(),
                rust_inside_history_flux.len(),
                rust_outside_current_outside.len(),
                rust_outside_current_inside.len(),
                rust_outside_history.len(),
            ]
            .into_iter()
            .min()
            .unwrap_or(0);
            if samples == 0 {
                return None;
            }

            let mut oracle_inside_current_outside = Vec::with_capacity(samples);
            let mut oracle_inside_current_inside = Vec::with_capacity(samples);
            let mut oracle_inside_current = Vec::with_capacity(samples);
            let mut rust_inside_current = Vec::with_capacity(samples);
            let mut oracle_inside_history = Vec::with_capacity(samples);
            // EnergyPlus hourly outputs expose only the aggregate history term.
            // These zero-baseline summaries report Rust split magnitudes beside
            // the aggregate oracle-vs-Rust history mismatch.
            let zero_history_split = vec![0.0; samples];
            let mut oracle_outside_current_outside = Vec::with_capacity(samples);
            let mut oracle_outside_current_inside = Vec::with_capacity(samples);
            let mut oracle_outside_current = Vec::with_capacity(samples);
            let mut rust_outside_current = Vec::with_capacity(samples);
            let mut oracle_outside_history = Vec::with_capacity(samples);
            for index in 0..samples {
                let oracle_inside_current_outside_term_w =
                    area_m2 * oracle_outside_temperatures[index] * zero.cross_w_per_m2_k;
                let oracle_inside_current_inside_term_w =
                    -area_m2 * oracle_inside_temperatures[index] * zero.inside_w_per_m2_k;
                let oracle_inside_current_term_w = area_m2
                    * (oracle_outside_temperatures[index] * zero.cross_w_per_m2_k
                        - oracle_inside_temperatures[index] * zero.inside_w_per_m2_k);
                let oracle_outside_current_outside_term_w =
                    -area_m2 * oracle_outside_temperatures[index] * zero.outside_w_per_m2_k;
                let oracle_outside_current_inside_term_w =
                    area_m2 * oracle_inside_temperatures[index] * zero.cross_w_per_m2_k;
                let oracle_outside_current_term_w = -area_m2
                    * (oracle_outside_temperatures[index] * zero.outside_w_per_m2_k
                        - oracle_inside_temperatures[index] * zero.cross_w_per_m2_k);
                let rust_inside_current_term_w =
                    rust_inside_current_outside[index] + rust_inside_current_inside[index];
                let rust_outside_current_term_w =
                    rust_outside_current_outside[index] + rust_outside_current_inside[index];

                oracle_inside_current_outside.push(oracle_inside_current_outside_term_w);
                oracle_inside_current_inside.push(oracle_inside_current_inside_term_w);
                oracle_inside_current.push(oracle_inside_current_term_w);
                rust_inside_current.push(rust_inside_current_term_w);
                oracle_inside_history
                    .push(oracle_inside_conduction[index] - oracle_inside_current_term_w);
                oracle_outside_current_outside.push(oracle_outside_current_outside_term_w);
                oracle_outside_current_inside.push(oracle_outside_current_inside_term_w);
                oracle_outside_current.push(oracle_outside_current_term_w);
                rust_outside_current.push(rust_outside_current_term_w);
                oracle_outside_history
                    .push(oracle_outside_conduction[index] - oracle_outside_current_term_w);
            }

            Some(HeatBalanceCtfHistorySeriesDelta {
                key: surface.name.0.clone(),
                construction_name: construction.name.0.clone(),
                area_m2,
                samples,
                inside_current_outside_term_delta: delta_summary(
                    &oracle_inside_current_outside,
                    &rust_inside_current_outside,
                ),
                inside_current_inside_term_delta: delta_summary(
                    &oracle_inside_current_inside,
                    &rust_inside_current_inside,
                ),
                inside_current_delta: delta_summary(&oracle_inside_current, &rust_inside_current),
                inside_history_delta: delta_summary(&oracle_inside_history, &rust_inside_history),
                inside_history_temperature_term_delta: delta_summary(
                    &zero_history_split,
                    &rust_inside_history_temperature[..samples],
                ),
                inside_history_flux_term_delta: delta_summary(
                    &zero_history_split,
                    &rust_inside_history_flux[..samples],
                ),
                outside_current_outside_term_delta: delta_summary(
                    &oracle_outside_current_outside,
                    &rust_outside_current_outside,
                ),
                outside_current_inside_term_delta: delta_summary(
                    &oracle_outside_current_inside,
                    &rust_outside_current_inside,
                ),
                outside_current_delta: delta_summary(
                    &oracle_outside_current,
                    &rust_outside_current,
                ),
                outside_history_delta: delta_summary(
                    &oracle_outside_history,
                    &rust_outside_history,
                ),
            })
        })
        .collect()
}

fn heat_balance_surface_iteration_max_sample_trace(
    rows: &[HeatBalanceSurfaceIterationSampleTrace],
    storage_deltas: &[HeatBalanceCtfStorageMaxSampleDelta],
) -> Vec<HeatBalanceSurfaceIterationSampleTrace> {
    let Some(sample_index) = storage_deltas.first().map(|row| row.sample_index) else {
        return Vec::new();
    };
    rows.iter()
        .filter(|row| row.sample_index == sample_index)
        .cloned()
        .collect()
}
fn heat_balance_ctf_storage_max_sample_deltas(
    model: &SimulationModel,
    series: &[HeatBalanceSeriesDiagnostic],
    ctf_coefficients: &[ConstructionCtfCoefficientOverride],
    results: &ResultStore,
) -> Vec<HeatBalanceCtfStorageMaxSampleDelta> {
    let mut rows: Vec<_> = model
        .typed
        .surfaces
        .iter()
        .filter_map(|surface| {
            let construction = model
                .typed
                .constructions
                .iter()
                .find(|construction| construction.id == surface.construction)?;
            let zero = ctf_coefficients.iter().find(|coefficient| {
                coefficient.time_index == 0
                    && coefficient
                        .construction_name
                        .eq_ignore_ascii_case(&construction.name.0)
            })?;
            let storage_series =
                heat_balance_series(series, &surface.name.0, "Surface Heat Storage Rate")?;
            let storage_point = storage_series.delta.max_delta_sample?;
            let sample_index = storage_point.index;
            let area_m2 = surface_area_m2(&surface.vertices);
            if area_m2 <= 0.0 {
                return None;
            }

            let inside_temperature = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Inside Face Temperature",
                sample_index,
            )?;
            let outside_temperature = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Outside Face Temperature",
                sample_index,
            )?;
            let inside_conduction = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Inside Face Conduction Heat Transfer Rate",
                sample_index,
            )?;
            let outside_conduction = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Outside Face Conduction Heat Transfer Rate",
                sample_index,
            )?;
            let rust_inside_current_outside = heat_balance_result_series_value(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_CURRENT_OUTSIDE_TERM_RATE_VARIABLE,
                sample_index,
            )?;
            let rust_inside_current_inside = heat_balance_result_series_value(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_CURRENT_INSIDE_TERM_RATE_VARIABLE,
                sample_index,
            )?;
            let rust_inside_history = heat_balance_result_series_value(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_HISTORY_TERM_RATE_VARIABLE,
                sample_index,
            )?;
            let rust_inside_history_temperature = heat_balance_result_series_value(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_HISTORY_TEMPERATURE_TERM_RATE_VARIABLE,
                sample_index,
            )?;
            let rust_inside_history_flux = heat_balance_result_series_value(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_HISTORY_FLUX_TERM_RATE_VARIABLE,
                sample_index,
            )?;
            let rust_outside_current_outside = heat_balance_result_series_value(
                results,
                &surface.name.0,
                SURFACE_CTF_OUTSIDE_CURRENT_OUTSIDE_TERM_RATE_VARIABLE,
                sample_index,
            )?;
            let rust_outside_current_inside = heat_balance_result_series_value(
                results,
                &surface.name.0,
                SURFACE_CTF_OUTSIDE_CURRENT_INSIDE_TERM_RATE_VARIABLE,
                sample_index,
            )?;
            let rust_outside_history = heat_balance_result_series_value(
                results,
                &surface.name.0,
                SURFACE_CTF_OUTSIDE_HISTORY_TERM_RATE_VARIABLE,
                sample_index,
            )?;

            let oracle_inside_current_outside_term_w =
                area_m2 * outside_temperature.oracle_c * zero.cross_w_per_m2_k;
            let oracle_inside_current_inside_term_w =
                -area_m2 * inside_temperature.oracle_c * zero.inside_w_per_m2_k;
            let oracle_inside_current_term_w =
                oracle_inside_current_outside_term_w + oracle_inside_current_inside_term_w;
            let rust_inside_current_term_w =
                rust_inside_current_outside + rust_inside_current_inside;
            let inside_face_temperature_signed_delta_c =
                inside_temperature.oracle_c - inside_temperature.rust_c;
            let inside_face_temperature_delta_c = inside_face_temperature_signed_delta_c.abs();
            let outside_face_temperature_signed_delta_c =
                outside_temperature.oracle_c - outside_temperature.rust_c;
            let outside_face_temperature_delta_c = outside_face_temperature_signed_delta_c.abs();
            let inside_current_outside_term_signed_delta_w =
                oracle_inside_current_outside_term_w - rust_inside_current_outside;
            let inside_current_outside_term_delta_w =
                inside_current_outside_term_signed_delta_w.abs();
            let inside_current_inside_term_signed_delta_w =
                oracle_inside_current_inside_term_w - rust_inside_current_inside;
            let inside_current_inside_term_delta_w =
                inside_current_inside_term_signed_delta_w.abs();
            let inside_current_signed_delta_w =
                oracle_inside_current_term_w - rust_inside_current_term_w;
            let inside_current_delta_w = inside_current_signed_delta_w.abs();
            let inside_current_split_abs_sum_w =
                inside_current_outside_term_delta_w + inside_current_inside_term_delta_w;
            let inside_current_cancellation_delta_w =
                inside_current_split_abs_sum_w - inside_current_delta_w;
            let oracle_inside_history_term_w =
                inside_conduction.oracle_c - oracle_inside_current_term_w;
            let inside_history_signed_delta_w = oracle_inside_history_term_w - rust_inside_history;
            let inside_history_delta_w = inside_history_signed_delta_w.abs();
            let oracle_outside_current_term_w = -area_m2
                * (outside_temperature.oracle_c * zero.outside_w_per_m2_k
                    - inside_temperature.oracle_c * zero.cross_w_per_m2_k);
            let rust_outside_current_term_w =
                rust_outside_current_outside + rust_outside_current_inside;
            let oracle_outside_history_term_w =
                outside_conduction.oracle_c - oracle_outside_current_term_w;
            let outside_current_delta_w =
                (oracle_outside_current_term_w - rust_outside_current_term_w).abs();
            let outside_history_delta_w =
                (oracle_outside_history_term_w - rust_outside_history).abs();
            let oracle_storage_from_conduction_w =
                -(inside_conduction.oracle_c + outside_conduction.oracle_c);
            let rust_storage_from_conduction_w =
                -(inside_conduction.rust_c + outside_conduction.rust_c);
            let storage_from_conduction_signed_delta_w =
                oracle_storage_from_conduction_w - rust_storage_from_conduction_w;
            let storage_from_conduction_delta_w = storage_from_conduction_signed_delta_w.abs();
            let oracle_storage_balance_residual_w =
                storage_point.oracle_c - oracle_storage_from_conduction_w;
            let rust_storage_balance_residual_w =
                storage_point.rust_c - rust_storage_from_conduction_w;
            let storage_balance_residual_delta_w =
                (oracle_storage_balance_residual_w - rust_storage_balance_residual_w).abs();
            let (dominant_mismatch_source, dominant_mismatch_delta_w) = [
                (
                    "face-temperature-current-outside",
                    inside_current_outside_term_delta_w,
                ),
                (
                    "face-temperature-current-inside",
                    inside_current_inside_term_delta_w,
                ),
                ("history-vector-inside-total", inside_history_delta_w),
                ("outside-current-total", outside_current_delta_w),
                ("outside-history-total", outside_history_delta_w),
                (
                    "output-aggregation-storage-balance",
                    storage_balance_residual_delta_w,
                ),
            ]
            .into_iter()
            .max_by(|left, right| left.1.total_cmp(&right.1))
            .unwrap_or(("unknown", 0.0));

            Some(HeatBalanceCtfStorageMaxSampleDelta {
                key: surface.name.0.clone(),
                construction_name: construction.name.0.clone(),
                storage_delta_rank: 0,
                dominant_storage_surface: false,
                sample_index,
                area_m2,
                ctf_inside_0_w_per_m2_k: zero.inside_w_per_m2_k,
                ctf_cross_0_w_per_m2_k: zero.cross_w_per_m2_k,
                ctf_outside_0_w_per_m2_k: zero.outside_w_per_m2_k,
                oracle_inside_face_temperature_c: inside_temperature.oracle_c,
                rust_inside_face_temperature_c: inside_temperature.rust_c,
                inside_face_temperature_signed_delta_c,
                inside_face_temperature_delta_c,
                oracle_outside_face_temperature_c: outside_temperature.oracle_c,
                rust_outside_face_temperature_c: outside_temperature.rust_c,
                outside_face_temperature_signed_delta_c,
                outside_face_temperature_delta_c,
                oracle_inside_conduction_w: inside_conduction.oracle_c,
                rust_inside_conduction_w: inside_conduction.rust_c,
                inside_conduction_delta_w: inside_conduction.abs_delta_c,
                oracle_outside_conduction_w: outside_conduction.oracle_c,
                rust_outside_conduction_w: outside_conduction.rust_c,
                outside_conduction_delta_w: outside_conduction.abs_delta_c,
                oracle_storage_w: storage_point.oracle_c,
                rust_storage_w: storage_point.rust_c,
                storage_delta_w: storage_point.abs_delta_c,
                oracle_storage_from_conduction_w,
                rust_storage_from_conduction_w,
                storage_from_conduction_signed_delta_w,
                storage_from_conduction_delta_w,
                oracle_storage_balance_residual_w,
                rust_storage_balance_residual_w,
                storage_balance_residual_delta_w,
                dominant_mismatch_source: dominant_mismatch_source.to_string(),
                dominant_mismatch_delta_w,
                oracle_inside_current_outside_term_w,
                rust_inside_current_outside_term_w: rust_inside_current_outside,
                inside_current_outside_term_signed_delta_w,
                inside_current_outside_term_delta_w,
                oracle_inside_current_inside_term_w,
                rust_inside_current_inside_term_w: rust_inside_current_inside,
                inside_current_inside_term_signed_delta_w,
                inside_current_inside_term_delta_w,
                oracle_inside_current_term_w,
                rust_inside_current_term_w,
                inside_current_signed_delta_w,
                inside_current_delta_w,
                inside_current_split_abs_sum_w,
                inside_current_cancellation_delta_w,
                oracle_inside_history_term_w,
                rust_inside_history_term_w: rust_inside_history,
                inside_history_signed_delta_w,
                inside_history_delta_w,
                rust_inside_history_temperature_term_w: rust_inside_history_temperature,
                rust_inside_history_flux_term_w: rust_inside_history_flux,
                oracle_outside_current_term_w,
                rust_outside_current_term_w,
                outside_current_delta_w,
                oracle_outside_history_term_w,
                rust_outside_history_term_w: rust_outside_history,
                outside_history_delta_w,
            })
        })
        .collect();
    rows.sort_by(|left, right| right.storage_delta_w.total_cmp(&left.storage_delta_w));
    for (index, row) in rows.iter_mut().enumerate() {
        row.storage_delta_rank = index + 1;
        row.dominant_storage_surface = index == 0;
    }
    rows
}

fn heat_balance_inside_balance_max_sample_deltas(
    model: &SimulationModel,
    series: &[HeatBalanceSeriesDiagnostic],
) -> Vec<HeatBalanceInsideBalanceMaxSampleDelta> {
    model
        .typed
        .surfaces
        .iter()
        .filter_map(|surface| {
            let construction = model
                .typed
                .constructions
                .iter()
                .find(|construction| construction.id == surface.construction)?;
            let storage_series =
                heat_balance_series(series, &surface.name.0, "Surface Heat Storage Rate")?;
            let storage_point = storage_series.delta.max_delta_sample?;
            let sample_index = storage_point.index;
            let area_m2 = surface_area_m2(&surface.vertices);
            if area_m2 <= 0.0 {
                return None;
            }

            let inside_temperature = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Inside Face Temperature",
                sample_index,
            )?;
            let inside_convection_coefficient = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Inside Face Convection Heat Transfer Coefficient",
                sample_index,
            )?;
            let inside_conduction = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Inside Face Conduction Heat Transfer Rate",
                sample_index,
            )?;
            let inside_convection = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Inside Face Convection Heat Gain Rate",
                sample_index,
            )?;
            let inside_net_longwave = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Inside Face Net Surface Thermal Radiation Heat Gain Rate",
                sample_index,
            )?;
            let oracle_inside_balance_residual_w = inside_conduction.oracle_c
                + inside_convection.oracle_c
                + inside_net_longwave.oracle_c;
            let rust_inside_balance_residual_w =
                inside_conduction.rust_c + inside_convection.rust_c + inside_net_longwave.rust_c;

            Some(HeatBalanceInsideBalanceMaxSampleDelta {
                key: surface.name.0.clone(),
                construction_name: construction.name.0.clone(),
                sample_index,
                area_m2,
                oracle_inside_face_temperature_c: inside_temperature.oracle_c,
                rust_inside_face_temperature_c: inside_temperature.rust_c,
                inside_face_temperature_delta_c: inside_temperature.abs_delta_c,
                oracle_inside_convection_coefficient_w_per_m2_k: inside_convection_coefficient
                    .oracle_c,
                rust_inside_convection_coefficient_w_per_m2_k: inside_convection_coefficient.rust_c,
                inside_convection_coefficient_delta_w_per_m2_k: inside_convection_coefficient
                    .abs_delta_c,
                oracle_inside_conduction_w: inside_conduction.oracle_c,
                rust_inside_conduction_w: inside_conduction.rust_c,
                inside_conduction_delta_w: inside_conduction.abs_delta_c,
                oracle_inside_convection_w: inside_convection.oracle_c,
                rust_inside_convection_w: inside_convection.rust_c,
                inside_convection_delta_w: inside_convection.abs_delta_c,
                oracle_inside_net_longwave_w: inside_net_longwave.oracle_c,
                rust_inside_net_longwave_w: inside_net_longwave.rust_c,
                inside_net_longwave_delta_w: inside_net_longwave.abs_delta_c,
                oracle_inside_balance_residual_w,
                rust_inside_balance_residual_w,
                inside_balance_residual_delta_w: (oracle_inside_balance_residual_w
                    - rust_inside_balance_residual_w)
                    .abs(),
            })
        })
        .collect()
}

fn heat_balance_inside_solve_max_sample_deltas(
    model: &SimulationModel,
    series: &[HeatBalanceSeriesDiagnostic],
    ctf_coefficients: &[ConstructionCtfCoefficientOverride],
    results: &ResultStore,
) -> Vec<HeatBalanceInsideSolveMaxSampleDelta> {
    model
        .typed
        .surfaces
        .iter()
        .filter_map(|surface| {
            let construction = model
                .typed
                .constructions
                .iter()
                .find(|construction| construction.id == surface.construction)?;
            let zero = ctf_coefficients.iter().find(|coefficient| {
                coefficient.time_index == 0
                    && coefficient
                        .construction_name
                        .eq_ignore_ascii_case(&construction.name.0)
            })?;
            let storage_series =
                heat_balance_series(series, &surface.name.0, "Surface Heat Storage Rate")?;
            let storage_point = storage_series.delta.max_delta_sample?;
            let sample_index = storage_point.index;
            let area_m2 = surface_area_m2(&surface.vertices);
            if area_m2 <= 0.0 {
                return None;
            }

            let inside_temperature = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Inside Face Temperature",
                sample_index,
            )?;
            let outside_temperature = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Outside Face Temperature",
                sample_index,
            )?;
            let inside_convection_coefficient = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Inside Face Convection Heat Transfer Coefficient",
                sample_index,
            )?;
            let inside_convection = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Inside Face Convection Heat Gain Rate",
                sample_index,
            )?;
            let inside_conduction = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Inside Face Conduction Heat Transfer Rate",
                sample_index,
            )?;
            let inside_net_longwave = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Inside Face Net Surface Thermal Radiation Heat Gain Rate",
                sample_index,
            )?;
            let rust_inside_history = heat_balance_result_series_value(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_HISTORY_TERM_RATE_VARIABLE,
                sample_index,
            )?;
            let rust_inside_history_temperature = heat_balance_result_series_value(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_HISTORY_TEMPERATURE_TERM_RATE_VARIABLE,
                sample_index,
            )?;
            let rust_inside_history_flux = heat_balance_result_series_value(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_HISTORY_FLUX_TERM_RATE_VARIABLE,
                sample_index,
            )?;
            let rust_inside_current_outside = heat_balance_result_series_value(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_CURRENT_OUTSIDE_TERM_RATE_VARIABLE,
                sample_index,
            )?;
            let rust_inside_current_inside = heat_balance_result_series_value(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_CURRENT_INSIDE_TERM_RATE_VARIABLE,
                sample_index,
            )?;

            let adiabatic_cross =
                if surface.outside_boundary_condition == OutsideBoundaryCondition::Adiabatic {
                    zero.cross_w_per_m2_k
                } else {
                    0.0
                };
            let oracle_solve_denominator_w_per_m2_k = zero.inside_w_per_m2_k - adiabatic_cross
                + inside_convection_coefficient.oracle_c
                + HEAT_BALANCE_INSIDE_SURFACE_ITER_DAMP_W_PER_M2_K;
            let rust_solve_denominator_w_per_m2_k = zero.inside_w_per_m2_k - adiabatic_cross
                + inside_convection_coefficient.rust_c
                + HEAT_BALANCE_INSIDE_SURFACE_ITER_DAMP_W_PER_M2_K;
            let oracle_inferred_reference_air_temperature_c =
                heat_balance_inferred_reference_air_temperature_c(
                    inside_temperature.oracle_c,
                    inside_convection_coefficient.oracle_c,
                    area_m2,
                    inside_convection.oracle_c,
                );
            let rust_inferred_reference_air_temperature_c =
                heat_balance_inferred_reference_air_temperature_c(
                    inside_temperature.rust_c,
                    inside_convection_coefficient.rust_c,
                    area_m2,
                    inside_convection.rust_c,
                );
            let oracle_reference_air_source_w = area_m2
                * inside_convection_coefficient.oracle_c
                * oracle_inferred_reference_air_temperature_c;
            let rust_reference_air_source_w = area_m2
                * inside_convection_coefficient.rust_c
                * rust_inferred_reference_air_temperature_c;
            let oracle_surface_temperature_sink_w_per_m2 =
                inside_convection_coefficient.oracle_c * inside_temperature.oracle_c;
            let rust_surface_temperature_sink_w_per_m2 =
                inside_convection_coefficient.rust_c * inside_temperature.rust_c;
            let oracle_surface_temperature_sink_w =
                area_m2 * oracle_surface_temperature_sink_w_per_m2;
            let rust_surface_temperature_sink_w = area_m2 * rust_surface_temperature_sink_w_per_m2;
            let oracle_outside_temperature_source_w = area_m2
                * heat_balance_inside_solve_outside_temperature_source_w_per_m2(
                    surface.outside_boundary_condition,
                    zero.cross_w_per_m2_k,
                    outside_temperature.oracle_c,
                );
            let rust_outside_temperature_source_w = area_m2
                * heat_balance_inside_solve_outside_temperature_source_w_per_m2(
                    surface.outside_boundary_condition,
                    zero.cross_w_per_m2_k,
                    outside_temperature.rust_c,
                );
            let oracle_inside_current_outside_term_w =
                area_m2 * outside_temperature.oracle_c * zero.cross_w_per_m2_k;
            let oracle_inside_current_inside_term_w =
                -area_m2 * inside_temperature.oracle_c * zero.inside_w_per_m2_k;
            let oracle_inside_current_term_w =
                oracle_inside_current_outside_term_w + oracle_inside_current_inside_term_w;
            let rust_inside_current_term_w =
                rust_inside_current_outside + rust_inside_current_inside;
            let inside_conduction_signed_delta_w =
                inside_conduction.oracle_c - inside_conduction.rust_c;
            let inside_conduction_delta_w = inside_conduction.abs_delta_c;
            let inside_current_outside_term_signed_delta_w =
                oracle_inside_current_outside_term_w - rust_inside_current_outside;
            let inside_current_outside_term_delta_w =
                inside_current_outside_term_signed_delta_w.abs();
            let inside_current_inside_term_signed_delta_w =
                oracle_inside_current_inside_term_w - rust_inside_current_inside;
            let inside_current_inside_term_delta_w =
                inside_current_inside_term_signed_delta_w.abs();
            let inside_current_signed_delta_w =
                oracle_inside_current_term_w - rust_inside_current_term_w;
            let inside_current_delta_w = inside_current_signed_delta_w.abs();
            let inside_current_split_abs_sum_w =
                inside_current_outside_term_delta_w + inside_current_inside_term_delta_w;
            let inside_current_cancellation_delta_w =
                inside_current_split_abs_sum_w - inside_current_delta_w;
            let oracle_inside_history_term_w =
                inside_conduction.oracle_c - oracle_inside_current_term_w;
            let inside_history_signed_delta_w = oracle_inside_history_term_w - rust_inside_history;
            let oracle_implied_solve_numerator_w =
                area_m2 * oracle_solve_denominator_w_per_m2_k * inside_temperature.oracle_c;
            let rust_implied_solve_numerator_w =
                area_m2 * rust_solve_denominator_w_per_m2_k * inside_temperature.rust_c;
            let implied_solve_numerator_delta_w =
                (oracle_implied_solve_numerator_w - rust_implied_solve_numerator_w).abs();
            let solve_temperature_delta_component_w = (area_m2
                * oracle_solve_denominator_w_per_m2_k
                * (inside_temperature.oracle_c - inside_temperature.rust_c))
                .abs();
            let solve_denominator_delta_component_w = (area_m2
                * inside_temperature.rust_c
                * (oracle_solve_denominator_w_per_m2_k - rust_solve_denominator_w_per_m2_k))
                .abs();
            let reference_air_source_delta_w =
                (oracle_reference_air_source_w - rust_reference_air_source_w).abs();
            let reference_air_source_signed_delta_w =
                oracle_reference_air_source_w - rust_reference_air_source_w;
            let reference_air_coefficient_source_signed_delta_w = area_m2
                * (inside_convection_coefficient.oracle_c - inside_convection_coefficient.rust_c)
                * oracle_inferred_reference_air_temperature_c;
            let reference_air_coefficient_source_delta_w =
                reference_air_coefficient_source_signed_delta_w.abs();
            let reference_air_temperature_source_signed_delta_w = area_m2
                * inside_convection_coefficient.rust_c
                * (oracle_inferred_reference_air_temperature_c
                    - rust_inferred_reference_air_temperature_c);
            let reference_air_temperature_source_delta_w =
                reference_air_temperature_source_signed_delta_w.abs();
            let reference_air_source_split_abs_sum_w =
                reference_air_coefficient_source_delta_w + reference_air_temperature_source_delta_w;
            let reference_air_source_cancellation_delta_w =
                reference_air_source_split_abs_sum_w - reference_air_source_delta_w;
            let outside_temperature_source_delta_w =
                (oracle_outside_temperature_source_w - rust_outside_temperature_source_w).abs();
            let inside_history_delta_w = inside_history_signed_delta_w.abs();
            let inside_net_longwave_delta_w = inside_net_longwave.abs_delta_c;
            let tracked_solve_source_delta_w = reference_air_source_delta_w
                + outside_temperature_source_delta_w
                + inside_history_delta_w
                + inside_net_longwave_delta_w;
            let solve_source_residual_delta_w =
                implied_solve_numerator_delta_w - tracked_solve_source_delta_w;

            Some(HeatBalanceInsideSolveMaxSampleDelta {
                key: surface.name.0.clone(),
                construction_name: construction.name.0.clone(),
                outside_boundary_condition: heat_balance_outside_boundary_condition_label(
                    surface.outside_boundary_condition,
                )
                .to_string(),
                sample_index,
                area_m2,
                ctf_inside_0_w_per_m2_k: zero.inside_w_per_m2_k,
                ctf_cross_0_w_per_m2_k: zero.cross_w_per_m2_k,
                iter_damp_w_per_m2_k: HEAT_BALANCE_INSIDE_SURFACE_ITER_DAMP_W_PER_M2_K,
                oracle_inside_face_temperature_c: inside_temperature.oracle_c,
                rust_inside_face_temperature_c: inside_temperature.rust_c,
                inside_face_temperature_delta_c: inside_temperature.abs_delta_c,
                oracle_inferred_reference_air_temperature_c,
                rust_inferred_reference_air_temperature_c,
                inferred_reference_air_temperature_delta_c:
                    (oracle_inferred_reference_air_temperature_c
                        - rust_inferred_reference_air_temperature_c)
                        .abs(),
                oracle_inside_convection_coefficient_w_per_m2_k: inside_convection_coefficient
                    .oracle_c,
                rust_inside_convection_coefficient_w_per_m2_k: inside_convection_coefficient.rust_c,
                inside_convection_coefficient_delta_w_per_m2_k: inside_convection_coefficient
                    .abs_delta_c,
                oracle_solve_denominator_w_per_m2_k,
                rust_solve_denominator_w_per_m2_k,
                solve_denominator_delta_w_per_m2_k: (oracle_solve_denominator_w_per_m2_k
                    - rust_solve_denominator_w_per_m2_k)
                    .abs(),
                solve_temperature_delta_component_w,
                solve_denominator_delta_component_w,
                oracle_implied_solve_numerator_w,
                rust_implied_solve_numerator_w,
                implied_solve_numerator_delta_w,
                oracle_reference_air_source_w,
                rust_reference_air_source_w,
                reference_air_source_delta_w,
                reference_air_source_signed_delta_w,
                reference_air_source_split_abs_sum_w,
                reference_air_source_cancellation_delta_w,
                oracle_surface_temperature_sink_w,
                rust_surface_temperature_sink_w,
                surface_temperature_sink_delta_w: (oracle_surface_temperature_sink_w
                    - rust_surface_temperature_sink_w)
                    .abs(),
                oracle_surface_temperature_sink_w_per_m2,
                rust_surface_temperature_sink_w_per_m2,
                surface_temperature_sink_delta_w_per_m2: (oracle_surface_temperature_sink_w_per_m2
                    - rust_surface_temperature_sink_w_per_m2)
                    .abs(),
                reference_air_coefficient_source_signed_delta_w,
                reference_air_coefficient_source_delta_w,
                reference_air_temperature_source_signed_delta_w,
                reference_air_temperature_source_delta_w,
                oracle_outside_temperature_source_w,
                rust_outside_temperature_source_w,
                outside_temperature_source_delta_w,
                oracle_inside_conduction_w: inside_conduction.oracle_c,
                rust_inside_conduction_w: inside_conduction.rust_c,
                inside_conduction_signed_delta_w,
                inside_conduction_delta_w,
                oracle_inside_current_outside_term_w,
                rust_inside_current_outside_term_w: rust_inside_current_outside,
                inside_current_outside_term_signed_delta_w,
                inside_current_outside_term_delta_w,
                oracle_inside_current_inside_term_w,
                rust_inside_current_inside_term_w: rust_inside_current_inside,
                inside_current_inside_term_signed_delta_w,
                inside_current_inside_term_delta_w,
                oracle_inside_current_term_w,
                rust_inside_current_term_w,
                inside_current_signed_delta_w,
                inside_current_delta_w,
                inside_current_split_abs_sum_w,
                inside_current_cancellation_delta_w,
                oracle_inside_history_term_w,
                rust_inside_history_term_w: rust_inside_history,
                inside_history_signed_delta_w,
                inside_history_delta_w,
                rust_inside_history_temperature_term_w: rust_inside_history_temperature,
                rust_inside_history_flux_term_w: rust_inside_history_flux,
                oracle_inside_net_longwave_w: inside_net_longwave.oracle_c,
                rust_inside_net_longwave_w: inside_net_longwave.rust_c,
                inside_net_longwave_delta_w,
                tracked_solve_source_delta_w,
                solve_source_residual_delta_w,
                tracked_solve_source_coverage_ratio: heat_balance_ratio_or_zero(
                    tracked_solve_source_delta_w,
                    implied_solve_numerator_delta_w,
                ),
                solve_temperature_delta_component_share: heat_balance_ratio_or_zero(
                    solve_temperature_delta_component_w,
                    implied_solve_numerator_delta_w,
                ),
                solve_denominator_delta_component_share: heat_balance_ratio_or_zero(
                    solve_denominator_delta_component_w,
                    implied_solve_numerator_delta_w,
                ),
                reference_air_source_share: heat_balance_ratio_or_zero(
                    reference_air_source_delta_w,
                    implied_solve_numerator_delta_w,
                ),
                reference_air_coefficient_source_share: heat_balance_ratio_or_zero(
                    reference_air_coefficient_source_delta_w,
                    implied_solve_numerator_delta_w,
                ),
                reference_air_temperature_source_share: heat_balance_ratio_or_zero(
                    reference_air_temperature_source_delta_w,
                    implied_solve_numerator_delta_w,
                ),
                outside_temperature_source_share: heat_balance_ratio_or_zero(
                    outside_temperature_source_delta_w,
                    implied_solve_numerator_delta_w,
                ),
                inside_history_source_share: heat_balance_ratio_or_zero(
                    inside_history_delta_w,
                    implied_solve_numerator_delta_w,
                ),
                inside_net_longwave_source_share: heat_balance_ratio_or_zero(
                    inside_net_longwave_delta_w,
                    implied_solve_numerator_delta_w,
                ),
                solve_source_residual_share: heat_balance_ratio_or_zero(
                    solve_source_residual_delta_w,
                    implied_solve_numerator_delta_w,
                ),
            })
        })
        .collect()
}

fn heat_balance_inside_solve_series_deltas(
    model: &SimulationModel,
    series: &[HeatBalanceSeriesDiagnostic],
    ctf_coefficients: &[ConstructionCtfCoefficientOverride],
    results: &ResultStore,
) -> Vec<HeatBalanceInsideSolveSeriesDelta> {
    model
        .typed
        .surfaces
        .iter()
        .filter_map(|surface| {
            let construction = model
                .typed
                .constructions
                .iter()
                .find(|construction| construction.id == surface.construction)?;
            let zero = ctf_coefficients.iter().find(|coefficient| {
                coefficient.time_index == 0
                    && coefficient
                        .construction_name
                        .eq_ignore_ascii_case(&construction.name.0)
            })?;
            let area_m2 = surface_area_m2(&surface.vertices);
            if area_m2 <= 0.0 {
                return None;
            }

            let inside_temperature =
                heat_balance_series(series, &surface.name.0, "Surface Inside Face Temperature")?;
            let outside_temperature =
                heat_balance_series(series, &surface.name.0, "Surface Outside Face Temperature")?;
            let inside_convection_coefficient = heat_balance_series(
                series,
                &surface.name.0,
                "Surface Inside Face Convection Heat Transfer Coefficient",
            )?;
            let inside_convection = heat_balance_series(
                series,
                &surface.name.0,
                "Surface Inside Face Convection Heat Gain Rate",
            )?;
            let inside_conduction = heat_balance_series(
                series,
                &surface.name.0,
                "Surface Inside Face Conduction Heat Transfer Rate",
            )?;
            let inside_net_longwave = heat_balance_series(
                series,
                &surface.name.0,
                "Surface Inside Face Net Surface Thermal Radiation Heat Gain Rate",
            )?;
            let rust_inside_history = heat_balance_result_series_values(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_HISTORY_TERM_RATE_VARIABLE,
            )?;
            let rust_inside_current_outside = heat_balance_result_series_values(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_CURRENT_OUTSIDE_TERM_RATE_VARIABLE,
            )?;
            let rust_inside_current_inside = heat_balance_result_series_values(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_CURRENT_INSIDE_TERM_RATE_VARIABLE,
            )?;

            let samples = [
                inside_temperature.sample_rows.len(),
                outside_temperature.sample_rows.len(),
                inside_convection_coefficient.sample_rows.len(),
                inside_convection.sample_rows.len(),
                inside_conduction.sample_rows.len(),
                inside_net_longwave.sample_rows.len(),
                rust_inside_history.len(),
                rust_inside_current_outside.len(),
                rust_inside_current_inside.len(),
            ]
            .into_iter()
            .min()
            .unwrap_or(0);
            if samples == 0 {
                return None;
            }

            let mut oracle_inside_temperature = Vec::with_capacity(samples);
            let mut rust_inside_temperature = Vec::with_capacity(samples);
            let mut implied_solve_numerator_signed_delta = Vec::with_capacity(samples);
            let mut reference_air_source_signed_delta = Vec::with_capacity(samples);
            let mut reference_air_coefficient_source_signed_delta = Vec::with_capacity(samples);
            let mut reference_air_temperature_source_signed_delta = Vec::with_capacity(samples);
            let mut outside_temperature_source_signed_delta = Vec::with_capacity(samples);
            let mut inside_history_signed_delta = Vec::with_capacity(samples);
            let mut inside_net_longwave_signed_delta = Vec::with_capacity(samples);
            let mut tracked_solve_source_signed_delta = Vec::with_capacity(samples);
            let mut solve_source_residual_signed_delta = Vec::with_capacity(samples);
            let adiabatic_cross =
                if surface.outside_boundary_condition == OutsideBoundaryCondition::Adiabatic {
                    zero.cross_w_per_m2_k
                } else {
                    0.0
                };

            for index in 0..samples {
                let inside_temperature_point = inside_temperature.sample_rows[index];
                let outside_temperature_point = outside_temperature.sample_rows[index];
                let inside_hconv_point = inside_convection_coefficient.sample_rows[index];
                let inside_convection_point = inside_convection.sample_rows[index];
                let inside_conduction_point = inside_conduction.sample_rows[index];
                let inside_net_longwave_point = inside_net_longwave.sample_rows[index];

                oracle_inside_temperature.push(inside_temperature_point.oracle_c);
                rust_inside_temperature.push(inside_temperature_point.rust_c);

                let oracle_solve_denominator_w_per_m2_k = zero.inside_w_per_m2_k - adiabatic_cross
                    + inside_hconv_point.oracle_c
                    + HEAT_BALANCE_INSIDE_SURFACE_ITER_DAMP_W_PER_M2_K;
                let rust_solve_denominator_w_per_m2_k = zero.inside_w_per_m2_k - adiabatic_cross
                    + inside_hconv_point.rust_c
                    + HEAT_BALANCE_INSIDE_SURFACE_ITER_DAMP_W_PER_M2_K;
                let oracle_inferred_reference_air_temperature_c =
                    heat_balance_inferred_reference_air_temperature_c(
                        inside_temperature_point.oracle_c,
                        inside_hconv_point.oracle_c,
                        area_m2,
                        inside_convection_point.oracle_c,
                    );
                let rust_inferred_reference_air_temperature_c =
                    heat_balance_inferred_reference_air_temperature_c(
                        inside_temperature_point.rust_c,
                        inside_hconv_point.rust_c,
                        area_m2,
                        inside_convection_point.rust_c,
                    );
                let oracle_reference_air_source_w = area_m2
                    * inside_hconv_point.oracle_c
                    * oracle_inferred_reference_air_temperature_c;
                let rust_reference_air_source_w =
                    area_m2 * inside_hconv_point.rust_c * rust_inferred_reference_air_temperature_c;
                let reference_air_signed_delta_w =
                    oracle_reference_air_source_w - rust_reference_air_source_w;
                let reference_air_coefficient_signed_delta_w = area_m2
                    * (inside_hconv_point.oracle_c - inside_hconv_point.rust_c)
                    * oracle_inferred_reference_air_temperature_c;
                let reference_air_temperature_signed_delta_w = area_m2
                    * inside_hconv_point.rust_c
                    * (oracle_inferred_reference_air_temperature_c
                        - rust_inferred_reference_air_temperature_c);
                let oracle_outside_temperature_source_w = area_m2
                    * heat_balance_inside_solve_outside_temperature_source_w_per_m2(
                        surface.outside_boundary_condition,
                        zero.cross_w_per_m2_k,
                        outside_temperature_point.oracle_c,
                    );
                let rust_outside_temperature_source_w = area_m2
                    * heat_balance_inside_solve_outside_temperature_source_w_per_m2(
                        surface.outside_boundary_condition,
                        zero.cross_w_per_m2_k,
                        outside_temperature_point.rust_c,
                    );
                let outside_temperature_source_signed_delta_w =
                    oracle_outside_temperature_source_w - rust_outside_temperature_source_w;
                let oracle_inside_current_outside_term_w =
                    area_m2 * outside_temperature_point.oracle_c * zero.cross_w_per_m2_k;
                let oracle_inside_current_inside_term_w =
                    -area_m2 * inside_temperature_point.oracle_c * zero.inside_w_per_m2_k;
                let oracle_inside_current_term_w =
                    oracle_inside_current_outside_term_w + oracle_inside_current_inside_term_w;
                let oracle_inside_history_term_w =
                    inside_conduction_point.oracle_c - oracle_inside_current_term_w;
                let rust_inside_history_term_w = rust_inside_history[index];
                let inside_history_signed_delta_w =
                    oracle_inside_history_term_w - rust_inside_history_term_w;
                let inside_net_longwave_signed_delta_w =
                    inside_net_longwave_point.oracle_c - inside_net_longwave_point.rust_c;
                let oracle_implied_solve_numerator_w = area_m2
                    * oracle_solve_denominator_w_per_m2_k
                    * inside_temperature_point.oracle_c;
                let rust_implied_solve_numerator_w =
                    area_m2 * rust_solve_denominator_w_per_m2_k * inside_temperature_point.rust_c;
                let implied_solve_numerator_signed_delta_w =
                    oracle_implied_solve_numerator_w - rust_implied_solve_numerator_w;
                let tracked_source_signed_delta_w = reference_air_signed_delta_w
                    + outside_temperature_source_signed_delta_w
                    + inside_history_signed_delta_w
                    + inside_net_longwave_signed_delta_w;

                implied_solve_numerator_signed_delta.push(implied_solve_numerator_signed_delta_w);
                reference_air_source_signed_delta.push(reference_air_signed_delta_w);
                reference_air_coefficient_source_signed_delta
                    .push(reference_air_coefficient_signed_delta_w);
                reference_air_temperature_source_signed_delta
                    .push(reference_air_temperature_signed_delta_w);
                outside_temperature_source_signed_delta
                    .push(outside_temperature_source_signed_delta_w);
                inside_history_signed_delta.push(inside_history_signed_delta_w);
                inside_net_longwave_signed_delta.push(inside_net_longwave_signed_delta_w);
                tracked_solve_source_signed_delta.push(tracked_source_signed_delta_w);
                solve_source_residual_signed_delta
                    .push(implied_solve_numerator_signed_delta_w - tracked_source_signed_delta_w);
            }

            let zero_baseline = vec![0.0; samples];
            Some(HeatBalanceInsideSolveSeriesDelta {
                key: surface.name.0.clone(),
                construction_name: construction.name.0.clone(),
                outside_boundary_condition: heat_balance_outside_boundary_condition_label(
                    surface.outside_boundary_condition,
                )
                .to_string(),
                area_m2,
                samples,
                inside_face_temperature_delta: delta_summary(
                    &oracle_inside_temperature,
                    &rust_inside_temperature,
                ),
                implied_solve_numerator_delta: delta_summary(
                    &zero_baseline,
                    &implied_solve_numerator_signed_delta,
                ),
                reference_air_source_delta: delta_summary(
                    &zero_baseline,
                    &reference_air_source_signed_delta,
                ),
                reference_air_coefficient_source_delta: delta_summary(
                    &zero_baseline,
                    &reference_air_coefficient_source_signed_delta,
                ),
                reference_air_temperature_source_delta: delta_summary(
                    &zero_baseline,
                    &reference_air_temperature_source_signed_delta,
                ),
                outside_temperature_source_delta: delta_summary(
                    &zero_baseline,
                    &outside_temperature_source_signed_delta,
                ),
                inside_history_delta: delta_summary(&zero_baseline, &inside_history_signed_delta),
                inside_net_longwave_delta: delta_summary(
                    &zero_baseline,
                    &inside_net_longwave_signed_delta,
                ),
                tracked_solve_source_delta: delta_summary(
                    &zero_baseline,
                    &tracked_solve_source_signed_delta,
                ),
                solve_source_residual_delta: delta_summary(
                    &zero_baseline,
                    &solve_source_residual_signed_delta,
                ),
            })
        })
        .collect()
}

fn heat_balance_inside_source_term_series_summaries(
    model: &SimulationModel,
    results: &ResultStore,
) -> Vec<HeatBalanceInsideSourceTermSeriesSummary> {
    let mut rows = Vec::new();
    for surface in &model.typed.surfaces {
        let area_m2 = surface_area_m2(&surface.vertices);
        if area_m2 <= 0.0 {
            continue;
        }

        for (term_name, rate_variable, per_area_variable) in
            heat_balance_inside_source_term_definitions()
        {
            let Some(rate_values) =
                heat_balance_result_series_values(results, &surface.name.0, rate_variable)
            else {
                continue;
            };
            let Some(per_area_values) =
                heat_balance_result_series_values(results, &surface.name.0, per_area_variable)
            else {
                continue;
            };
            let samples = rate_values.len().min(per_area_values.len());
            if samples == 0 {
                continue;
            }

            let mut max_abs_w: f64 = 0.0;
            let mut max_abs_w_per_m2: f64 = 0.0;
            let mut area_residual_max_abs_w: f64 = 0.0;
            for index in 0..samples {
                let rate_w = rate_values[index];
                let per_area_w_per_m2 = per_area_values[index];
                if rate_w.is_finite() {
                    max_abs_w = max_abs_w.max(rate_w.abs());
                }
                if per_area_w_per_m2.is_finite() {
                    max_abs_w_per_m2 = max_abs_w_per_m2.max(per_area_w_per_m2.abs());
                }
                if rate_w.is_finite() && per_area_w_per_m2.is_finite() {
                    area_residual_max_abs_w =
                        area_residual_max_abs_w.max((rate_w - per_area_w_per_m2 * area_m2).abs());
                }
            }

            rows.push(HeatBalanceInsideSourceTermSeriesSummary {
                key: surface.name.0.clone(),
                term_name: term_name.to_string(),
                area_m2,
                samples,
                rate_variable: rate_variable.to_string(),
                per_area_variable: per_area_variable.to_string(),
                max_abs_w,
                max_abs_w_per_m2,
                area_residual_max_abs_w,
            });
        }
    }

    rows
}

fn heat_balance_inside_source_term_definitions() -> [(&'static str, &'static str, &'static str); 6]
{
    [
        (
            "inside-net-longwave",
            "Surface Inside Face Net Surface Thermal Radiation Heat Gain Rate",
            "Surface Inside Face Net Surface Thermal Radiation Heat Gain Rate per Area",
        ),
        (
            "radiant-internal-gain",
            SURFACE_INSIDE_RADIANT_INTERNAL_GAIN_SOURCE_TERM_RATE_VARIABLE,
            SURFACE_INSIDE_RADIANT_INTERNAL_GAIN_SOURCE_TERM_RATE_PER_AREA_VARIABLE,
        ),
        (
            "shortwave-absorbed",
            SURFACE_INSIDE_SHORTWAVE_ABSORBED_SOURCE_TERM_RATE_VARIABLE,
            SURFACE_INSIDE_SHORTWAVE_ABSORBED_SOURCE_TERM_RATE_PER_AREA_VARIABLE,
        ),
        (
            "additional-inside-heat-source",
            SURFACE_INSIDE_ADDITIONAL_HEAT_SOURCE_TERM_RATE_VARIABLE,
            SURFACE_INSIDE_ADDITIONAL_HEAT_SOURCE_TERM_RATE_PER_AREA_VARIABLE,
        ),
        (
            "radiant-hvac",
            SURFACE_INSIDE_RADIANT_HVAC_SOURCE_TERM_RATE_VARIABLE,
            SURFACE_INSIDE_RADIANT_HVAC_SOURCE_TERM_RATE_PER_AREA_VARIABLE,
        ),
        (
            "total-source",
            SURFACE_INSIDE_TOTAL_SOURCE_TERM_RATE_VARIABLE,
            SURFACE_INSIDE_TOTAL_SOURCE_TERM_RATE_PER_AREA_VARIABLE,
        ),
    ]
}

fn heat_balance_floor_inside_current_diagnostics(
    model: &SimulationModel,
    series: &[HeatBalanceSeriesDiagnostic],
    ctf_coefficients: &[ConstructionCtfCoefficientOverride],
    results: &ResultStore,
    storage_deltas: &[HeatBalanceCtfStorageMaxSampleDelta],
) -> Vec<HeatBalanceFloorInsideCurrentDiagnostic> {
    storage_deltas
        .iter()
        .filter(|storage| heat_balance_is_floor_key(&storage.key, &storage.construction_name))
        .filter_map(|storage| {
            let surface = model
                .typed
                .surfaces
                .iter()
                .find(|surface| surface.name.0.eq_ignore_ascii_case(&storage.key))?;
            let construction = model
                .typed
                .constructions
                .iter()
                .find(|construction| construction.id == surface.construction)?;
            let zero = ctf_coefficients.iter().find(|coefficient| {
                coefficient.time_index == 0
                    && coefficient
                        .construction_name
                        .eq_ignore_ascii_case(&construction.name.0)
            })?;
            let area_m2 = surface_area_m2(&surface.vertices);
            if area_m2 <= 0.0 {
                return None;
            }
            let sample_index = storage.sample_index;
            let inside_temperature = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Inside Face Temperature",
                sample_index,
            )?;
            let reference_air_temperature = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Inside Face Adjacent Air Temperature",
                sample_index,
            )?;
            let hconv_int = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Inside Face Convection Heat Transfer Coefficient",
                sample_index,
            )?;
            let rust_inside_current_inside_term_w = heat_balance_result_series_value(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_CURRENT_INSIDE_TERM_RATE_VARIABLE,
                sample_index,
            )?;
            let oracle_inside_current_inside_term_w =
                heat_balance_inside_current_inside_term_rate_w_from_sources(
                    area_m2,
                    zero.inside_w_per_m2_k,
                    inside_temperature.oracle_c,
                );
            let rust_recomputed_inside_current_inside_term_w =
                heat_balance_inside_current_inside_term_rate_w_from_sources(
                    area_m2,
                    zero.inside_w_per_m2_k,
                    inside_temperature.rust_c,
                );
            let inside_face_temperature_signed_delta_c =
                inside_temperature.oracle_c - inside_temperature.rust_c;
            let inside_face_temperature_delta_c = inside_face_temperature_signed_delta_c.abs();
            let reference_air_temperature_signed_delta_c =
                reference_air_temperature.oracle_c - reference_air_temperature.rust_c;
            let reference_air_temperature_delta_c = reference_air_temperature_signed_delta_c.abs();
            let hconv_int_signed_delta_w_per_m2_k = hconv_int.oracle_c - hconv_int.rust_c;
            let hconv_int_delta_w_per_m2_k = hconv_int_signed_delta_w_per_m2_k.abs();
            let inside_current_inside_term_signed_delta_w =
                oracle_inside_current_inside_term_w - rust_inside_current_inside_term_w;
            let inside_current_inside_term_delta_w =
                inside_current_inside_term_signed_delta_w.abs();
            let temperature_timing_expected_signed_delta_w =
                oracle_inside_current_inside_term_w - rust_recomputed_inside_current_inside_term_w;
            let temperature_timing_expected_abs_delta_w =
                temperature_timing_expected_signed_delta_w.abs();
            let temperature_timing_coverage_ratio = heat_balance_ratio_or_zero(
                temperature_timing_expected_abs_delta_w,
                inside_current_inside_term_delta_w,
            );
            let coefficient_delta_w_per_m2_k = 0.0;
            let current_inside_mismatch_classification =
                heat_balance_floor_inside_current_classification(
                    zero.inside_w_per_m2_k,
                    inside_current_inside_term_delta_w,
                    temperature_timing_coverage_ratio,
                    reference_air_temperature_delta_c,
                    hconv_int_delta_w_per_m2_k,
                );
            let next_source_order_focus = match current_inside_mismatch_classification.as_str() {
                "temperature-timing" => "UpdateThermalHistories/source-order",
                "hconv-cadence" => "inside-convection-cadence",
                "coefficient" => "ctf-coefficient-source",
                "closed" => "none",
                _ => "surface-source-order-residual",
            }
            .to_string();

            Some(HeatBalanceFloorInsideCurrentDiagnostic {
                key: surface.name.0.clone(),
                construction_name: construction.name.0.clone(),
                sample_index,
                area_m2,
                ctf_inside_0_w_per_m2_k: zero.inside_w_per_m2_k,
                oracle_inside_face_temperature_c: inside_temperature.oracle_c,
                rust_inside_face_temperature_c: inside_temperature.rust_c,
                inside_face_temperature_signed_delta_c,
                inside_face_temperature_delta_c,
                oracle_reference_air_temperature_c: reference_air_temperature.oracle_c,
                rust_reference_air_temperature_c: reference_air_temperature.rust_c,
                reference_air_temperature_signed_delta_c,
                reference_air_temperature_delta_c,
                oracle_hconv_int_w_per_m2_k: hconv_int.oracle_c,
                rust_hconv_int_w_per_m2_k: hconv_int.rust_c,
                hconv_int_signed_delta_w_per_m2_k,
                hconv_int_delta_w_per_m2_k,
                oracle_inside_current_inside_term_w,
                rust_inside_current_inside_term_w,
                inside_current_inside_term_signed_delta_w,
                inside_current_inside_term_delta_w,
                temperature_timing_expected_signed_delta_w,
                temperature_timing_expected_abs_delta_w,
                temperature_timing_coverage_ratio,
                coefficient_delta_w_per_m2_k,
                current_inside_mismatch_classification,
                next_source_order_focus,
                max_sample_source_terms: heat_balance_inside_source_terms_at_sample(
                    series,
                    results,
                    &surface.name.0,
                    sample_index,
                ),
            })
        })
        .collect()
}

fn heat_balance_floor_inside_current_classification(
    ctf_inside_0_w_per_m2_k: f64,
    inside_current_inside_term_delta_w: f64,
    temperature_timing_coverage_ratio: f64,
    reference_air_temperature_delta_c: f64,
    hconv_int_delta_w_per_m2_k: f64,
) -> String {
    if !ctf_inside_0_w_per_m2_k.is_finite() {
        return "coefficient".to_string();
    }
    if inside_current_inside_term_delta_w <= 1.0e-9 {
        return "closed".to_string();
    }
    if temperature_timing_coverage_ratio >= 0.98 {
        return "temperature-timing".to_string();
    }
    if reference_air_temperature_delta_c > 1.0e-3 || hconv_int_delta_w_per_m2_k > 1.0e-6 {
        return "hconv-cadence".to_string();
    }
    "source-order-residual".to_string()
}

fn heat_balance_inside_current_inside_term_rate_w_from_sources(
    area_m2: f64,
    ctf_inside_0_w_per_m2_k: f64,
    inside_face_temperature_c: f64,
) -> f64 {
    if area_m2 <= 0.0 {
        return 0.0;
    }
    -area_m2 * inside_face_temperature_c * ctf_inside_0_w_per_m2_k
}

fn heat_balance_inside_source_terms_at_sample(
    series: &[HeatBalanceSeriesDiagnostic],
    results: &ResultStore,
    key: &str,
    sample_index: usize,
) -> Vec<HeatBalanceInsideSourceTermSampleDelta> {
    heat_balance_inside_source_term_definitions()
        .into_iter()
        .filter_map(|(term_name, rate_variable, _per_area_variable)| {
            let rust_w =
                heat_balance_result_series_value(results, key, rate_variable, sample_index)?;
            let point =
                heat_balance_sample_point_for_output(series, key, rate_variable, sample_index);
            let oracle_w = point.map_or(f64::NAN, |point| point.oracle_c);
            let signed_delta_w = point.map_or(f64::NAN, |point| point.oracle_c - point.rust_c);
            let abs_delta_w = point.map_or(f64::NAN, |point| point.abs_delta_c);
            Some(HeatBalanceInsideSourceTermSampleDelta {
                term_name: term_name.to_string(),
                rate_variable: rate_variable.to_string(),
                sample_index,
                oracle_w,
                rust_w,
                signed_delta_w,
                abs_delta_w,
            })
        })
        .collect()
}

fn heat_balance_floor_inside_current_term_series(
    model: &SimulationModel,
    series: &[HeatBalanceSeriesDiagnostic],
    ctf_coefficients: &[ConstructionCtfCoefficientOverride],
    results: &ResultStore,
) -> Vec<HeatBalanceFloorInsideCurrentTermSeries> {
    model
        .typed
        .surfaces
        .iter()
        .filter_map(|surface| {
            let construction = model
                .typed
                .constructions
                .iter()
                .find(|construction| construction.id == surface.construction)?;
            if !heat_balance_is_floor_key(&surface.name.0, &construction.name.0) {
                return None;
            }
            let zero = ctf_coefficients.iter().find(|coefficient| {
                coefficient.time_index == 0
                    && coefficient
                        .construction_name
                        .eq_ignore_ascii_case(&construction.name.0)
            })?;
            let area_m2 = surface_area_m2(&surface.vertices);
            if area_m2 <= 0.0 {
                return None;
            }
            let inside_temperature =
                heat_balance_series(series, &surface.name.0, "Surface Inside Face Temperature")?;
            let rust_inside_current_inside_terms = heat_balance_result_series_values(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_CURRENT_INSIDE_TERM_RATE_VARIABLE,
            )?;
            let samples = inside_temperature
                .sample_rows
                .len()
                .min(rust_inside_current_inside_terms.len());
            if samples == 0 {
                return None;
            }
            let mut sample_rows = Vec::with_capacity(samples);
            for index in 0..samples {
                let point = inside_temperature.sample_rows[index];
                let rust_inside_current_inside_term_w = rust_inside_current_inside_terms[index];
                if !rust_inside_current_inside_term_w.is_finite() {
                    continue;
                }
                let oracle_inside_current_inside_term_w =
                    heat_balance_inside_current_inside_term_rate_w_from_sources(
                        area_m2,
                        zero.inside_w_per_m2_k,
                        point.oracle_c,
                    );
                let signed_delta_w =
                    oracle_inside_current_inside_term_w - rust_inside_current_inside_term_w;
                sample_rows.push(HeatBalanceFloorInsideCurrentTermSample {
                    sample_index: point.index,
                    oracle_inside_face_temperature_c: point.oracle_c,
                    rust_inside_face_temperature_c: point.rust_c,
                    oracle_inside_current_inside_term_w,
                    rust_inside_current_inside_term_w,
                    signed_delta_w,
                    abs_delta_w: signed_delta_w.abs(),
                });
            }
            let max_row = sample_rows
                .iter()
                .max_by(|left, right| left.abs_delta_w.total_cmp(&right.abs_delta_w))?;
            let max_sample_index = max_row.sample_index;
            let max_abs_delta_w = max_row.abs_delta_w;
            let max_signed_delta_w = max_row.signed_delta_w;
            Some(HeatBalanceFloorInsideCurrentTermSeries {
                key: surface.name.0.clone(),
                construction_name: construction.name.0.clone(),
                area_m2,
                ctf_inside_0_w_per_m2_k: zero.inside_w_per_m2_k,
                samples: sample_rows.len(),
                max_sample_index,
                max_abs_delta_w,
                max_signed_delta_w,
                sample_rows,
            })
        })
        .collect()
}

fn heat_balance_ratio_or_zero(numerator: f64, denominator: f64) -> f64 {
    if denominator.abs() <= f64::EPSILON {
        0.0
    } else {
        numerator / denominator
    }
}

fn heat_balance_adiabatic_history_max_sample_deltas(
    model: &SimulationModel,
    series: &[HeatBalanceSeriesDiagnostic],
    ctf_coefficients: &[ConstructionCtfCoefficientOverride],
    results: &ResultStore,
) -> Vec<HeatBalanceAdiabaticHistoryMaxSampleDelta> {
    model
        .typed
        .surfaces
        .iter()
        .filter(|surface| surface.outside_boundary_condition == OutsideBoundaryCondition::Adiabatic)
        .filter_map(|surface| {
            let construction = model
                .typed
                .constructions
                .iter()
                .find(|construction| construction.id == surface.construction)?;
            let zero = ctf_coefficients.iter().find(|coefficient| {
                coefficient.time_index == 0
                    && coefficient
                        .construction_name
                        .eq_ignore_ascii_case(&construction.name.0)
            })?;
            let storage_series =
                heat_balance_series(series, &surface.name.0, "Surface Heat Storage Rate")?;
            let storage_point = storage_series.delta.max_delta_sample?;
            let sample_index = storage_point.index;
            let area_m2 = surface_area_m2(&surface.vertices);
            if area_m2 <= 0.0 {
                return None;
            }

            let inside_temperature = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Inside Face Temperature",
                sample_index,
            )?;
            let outside_temperature = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Outside Face Temperature",
                sample_index,
            )?;
            let inside_conduction = heat_balance_sample_point_for_output(
                series,
                &surface.name.0,
                "Surface Inside Face Conduction Heat Transfer Rate",
                sample_index,
            )?;
            let rust_inside_current_outside = heat_balance_result_series_value(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_CURRENT_OUTSIDE_TERM_RATE_VARIABLE,
                sample_index,
            )?;
            let rust_inside_current_inside = heat_balance_result_series_value(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_CURRENT_INSIDE_TERM_RATE_VARIABLE,
                sample_index,
            )?;
            let rust_inside_history = heat_balance_result_series_value(
                results,
                &surface.name.0,
                SURFACE_CTF_INSIDE_HISTORY_TERM_RATE_VARIABLE,
                sample_index,
            )?;

            let oracle_inside_current_term_w = area_m2
                * (outside_temperature.oracle_c * zero.cross_w_per_m2_k
                    - inside_temperature.oracle_c * zero.inside_w_per_m2_k);
            let rust_inside_current_term_w =
                rust_inside_current_outside + rust_inside_current_inside;
            let oracle_inside_current_if_outside_synced_w = area_m2
                * (inside_temperature.oracle_c * zero.cross_w_per_m2_k
                    - inside_temperature.oracle_c * zero.inside_w_per_m2_k);
            let rust_inside_current_if_outside_synced_w = area_m2
                * (inside_temperature.rust_c * zero.cross_w_per_m2_k
                    - inside_temperature.rust_c * zero.inside_w_per_m2_k);
            let oracle_inside_history_term_w =
                inside_conduction.oracle_c - oracle_inside_current_term_w;
            let oracle_inside_history_if_outside_synced_w =
                inside_conduction.oracle_c - oracle_inside_current_if_outside_synced_w;
            let rust_inside_history_if_outside_synced_w =
                inside_conduction.rust_c - rust_inside_current_if_outside_synced_w;
            let oracle_outside_minus_inside_c =
                outside_temperature.oracle_c - inside_temperature.oracle_c;
            let rust_outside_minus_inside_c =
                outside_temperature.rust_c - inside_temperature.rust_c;

            Some(HeatBalanceAdiabaticHistoryMaxSampleDelta {
                key: surface.name.0.clone(),
                construction_name: construction.name.0.clone(),
                sample_index,
                area_m2,
                ctf_inside_0_w_per_m2_k: zero.inside_w_per_m2_k,
                ctf_cross_0_w_per_m2_k: zero.cross_w_per_m2_k,
                oracle_inside_face_temperature_c: inside_temperature.oracle_c,
                rust_inside_face_temperature_c: inside_temperature.rust_c,
                inside_face_temperature_delta_c: inside_temperature.abs_delta_c,
                oracle_outside_face_temperature_c: outside_temperature.oracle_c,
                rust_outside_face_temperature_c: outside_temperature.rust_c,
                outside_face_temperature_delta_c: outside_temperature.abs_delta_c,
                oracle_outside_minus_inside_c,
                rust_outside_minus_inside_c,
                outside_minus_inside_delta_c: (oracle_outside_minus_inside_c
                    - rust_outside_minus_inside_c)
                    .abs(),
                oracle_inside_current_term_w,
                rust_inside_current_term_w,
                inside_current_delta_w: (oracle_inside_current_term_w - rust_inside_current_term_w)
                    .abs(),
                oracle_inside_current_if_outside_synced_w,
                rust_inside_current_if_outside_synced_w,
                inside_current_if_outside_synced_delta_w:
                    (oracle_inside_current_if_outside_synced_w
                        - rust_inside_current_if_outside_synced_w)
                        .abs(),
                oracle_inside_current_sync_shift_w: oracle_inside_current_if_outside_synced_w
                    - oracle_inside_current_term_w,
                rust_inside_current_sync_shift_w: rust_inside_current_if_outside_synced_w
                    - rust_inside_current_term_w,
                oracle_inside_history_term_w,
                rust_inside_history_term_w: rust_inside_history,
                inside_history_delta_w: (oracle_inside_history_term_w - rust_inside_history).abs(),
                oracle_inside_history_if_outside_synced_w,
                rust_inside_history_if_outside_synced_w,
                inside_history_if_outside_synced_delta_w:
                    (oracle_inside_history_if_outside_synced_w
                        - rust_inside_history_if_outside_synced_w)
                        .abs(),
            })
        })
        .collect()
}

fn heat_balance_ctf_history_max_sample_slots(
    model: &SimulationModel,
    series: &[HeatBalanceSeriesDiagnostic],
    hourly_slots: &[HeatBalanceCtfHistorySlotHourlySample],
) -> Vec<HeatBalanceCtfHistorySlotHourlySample> {
    let mut rows = Vec::new();
    for surface in &model.typed.surfaces {
        let Some(storage_series) =
            heat_balance_series(series, &surface.name.0, "Surface Heat Storage Rate")
        else {
            continue;
        };
        let Some(storage_point) = storage_series.delta.max_delta_sample else {
            continue;
        };
        rows.extend(
            hourly_slots
                .iter()
                .filter(|sample| {
                    sample.sample_index == storage_point.index
                        && sample.surface_name.eq_ignore_ascii_case(&surface.name.0)
                })
                .cloned(),
        );
    }
    rows
}

fn heat_balance_inferred_reference_air_temperature_c(
    inside_face_temperature_c: f64,
    inside_convection_coefficient_w_per_m2_k: f64,
    area_m2: f64,
    inside_convection_heat_gain_rate_w: f64,
) -> f64 {
    let conductance_w_per_k = inside_convection_coefficient_w_per_m2_k * area_m2;
    if conductance_w_per_k.abs() <= f64::EPSILON {
        f64::NAN
    } else {
        inside_face_temperature_c + inside_convection_heat_gain_rate_w / conductance_w_per_k
    }
}

fn heat_balance_inside_solve_outside_temperature_source_w_per_m2(
    outside_boundary_condition: OutsideBoundaryCondition,
    ctf_cross_0_w_per_m2_k: f64,
    outside_face_temperature_c: f64,
) -> f64 {
    if outside_boundary_condition == OutsideBoundaryCondition::Adiabatic {
        0.0
    } else {
        ctf_cross_0_w_per_m2_k * outside_face_temperature_c
    }
}

fn heat_balance_outside_boundary_condition_label(
    outside_boundary_condition: OutsideBoundaryCondition,
) -> &'static str {
    match outside_boundary_condition {
        OutsideBoundaryCondition::Adiabatic => "adiabatic",
        OutsideBoundaryCondition::Foundation => "foundation",
        OutsideBoundaryCondition::Ground => "ground",
        OutsideBoundaryCondition::Outdoors => "outdoors",
        OutsideBoundaryCondition::Space => "space",
        OutsideBoundaryCondition::Surface => "surface",
        OutsideBoundaryCondition::Zone => "zone",
        OutsideBoundaryCondition::Other => "other",
    }
}

fn heat_balance_oracle_series_values(
    series: &[HeatBalanceSeriesDiagnostic],
    key: &str,
    variable_name: &str,
) -> Option<Vec<f64>> {
    series
        .iter()
        .find(|series| {
            series.output.key.eq_ignore_ascii_case(key)
                && series.output.variable.eq_ignore_ascii_case(variable_name)
        })
        .map(|series| {
            series
                .sample_rows
                .iter()
                .map(|point| point.oracle_c)
                .collect::<Vec<_>>()
        })
}

fn heat_balance_result_series_values(
    results: &ResultStore,
    key: &str,
    variable_name: &str,
) -> Option<Vec<f64>> {
    results
        .find_series(key, variable_name)
        .map(|series| series.values.clone())
}

fn heat_balance_result_series_value(
    results: &ResultStore,
    key: &str,
    variable_name: &str,
    sample_index: usize,
) -> Option<f64> {
    results
        .find_series(key, variable_name)
        .and_then(|series| series.values.get(sample_index).copied())
        .filter(|value| value.is_finite())
}

fn heat_balance_series<'a>(
    series: &'a [HeatBalanceSeriesDiagnostic],
    key: &str,
    variable_name: &str,
) -> Option<&'a HeatBalanceSeriesDiagnostic> {
    series.iter().find(|series| {
        series.output.key.eq_ignore_ascii_case(key)
            && series.output.variable.eq_ignore_ascii_case(variable_name)
    })
}

fn heat_balance_sample_point_for_output(
    series: &[HeatBalanceSeriesDiagnostic],
    key: &str,
    variable_name: &str,
    sample_index: usize,
) -> Option<DeltaPoint> {
    heat_balance_series(series, key, variable_name)
        .and_then(|series| heat_balance_sample_point(series, sample_index))
}

