fn window_material_gas_rows(model: &TypedModel) -> Result<Vec<WindowMaterialGasRow>, String> {
    let mut rows = Vec::new();
    for construction in model
        .constructions
        .iter()
        .filter(|construction| construction.kind == ConstructionKind::Fenestration)
    {
        for material in materials_for_construction(model, construction)? {
            if let MaterialDefinition::WindowGas(fields) = material.definition {
                rows.push(WindowMaterialGasRow {
                    construction_name: construction.name.0.clone(),
                    material_name: material.name.0.clone(),
                    fields,
                });
            }
        }
    }
    Ok(rows)
}

#[derive(Clone, Debug)]
struct WindowMaterialGasMixtureRow {
    material_name: String,
    fields: WindowGasMixtureMaterial,
}

fn window_material_gas_mixture_rows(model: &TypedModel) -> Vec<WindowMaterialGasMixtureRow> {
    model
        .materials
        .iter()
        .filter_map(|material| {
            let MaterialDefinition::WindowGasMixture(fields) = material.definition else {
                return None;
            };
            Some(WindowMaterialGasMixtureRow {
                material_name: material.name.0.clone(),
                fields,
            })
        })
        .collect()
}

#[derive(Clone, Debug)]
struct WindowMaterialGapEquivalentLayerRow {
    construction_name: String,
    layer_number: usize,
    material_name: String,
    fields: WindowGapEquivalentLayerMaterial,
}

fn window_material_gap_equivalent_layer_rows(
    raw_model: &RawModel,
    model: &TypedModel,
) -> Result<Vec<WindowMaterialGapEquivalentLayerRow>, String> {
    const OBJECT_TYPE: &str = "Construction:WindowEquivalentLayer";
    const MAX_LAYERS: usize = 11;

    let constructions = raw_model
        .ordered_instances(OBJECT_TYPE)
        .map_err(|error| error.to_string())?;
    let mut rows = Vec::new();
    for (construction_name, construction) in constructions {
        let mut missing_optional_layer = false;
        for layer_number in 1..=MAX_LAYERS {
            let field_name = if layer_number == 1 {
                "outside_layer".to_string()
            } else {
                format!("layer_{layer_number}")
            };
            let Some(value) = construction
                .fields
                .iter()
                .find(|(field, _value)| field.0 == field_name)
                .map(|(_field, value)| value)
            else {
                if layer_number == 1 {
                    return Err(format!(
                        "{OBJECT_TYPE}/{} requires field outside_layer",
                        construction_name.0
                    ));
                }
                missing_optional_layer = true;
                continue;
            };
            if missing_optional_layer {
                return Err(format!(
                    "{OBJECT_TYPE}/{} has noncontiguous layer field {field_name}",
                    construction_name.0
                ));
            }
            let RawValue::String(material_name) = value else {
                return Err(format!(
                    "{OBJECT_TYPE}/{} field {field_name} must be a string",
                    construction_name.0
                ));
            };
            if material_name.trim().is_empty() {
                return Err(format!(
                    "{OBJECT_TYPE}/{} field {field_name} must be nonblank",
                    construction_name.0
                ));
            }

            let Some(material_id) = model.material_names.resolve(material_name) else {
                // Other equivalent-layer material objects remain outside the
                // current typed subset and do not emit this EIO row type.
                continue;
            };
            let material = model
                .materials
                .iter()
                .find(|material| material.id == material_id)
                .ok_or_else(|| {
                    format!(
                        "{OBJECT_TYPE}/{} field {field_name} references a missing typed material",
                        construction_name.0
                    )
                })?;
            let MaterialDefinition::WindowGapEquivalentLayer(fields) = material.definition else {
                continue;
            };
            rows.push(WindowMaterialGapEquivalentLayerRow {
                construction_name: construction_name.0.trim().to_ascii_uppercase(),
                layer_number,
                material_name: material.name.0.clone(),
                fields,
            });
        }
    }
    Ok(rows)
}

const fn window_gas_type_name(gas_type: WindowGasType) -> &'static str {
    gas_type.energyplus_name()
}

fn window_material_gas_pairings(
    rust_rows: &[WindowMaterialGasRow],
    oracle_rows: &[ep_compare::EioWindowMaterialGas],
) -> Vec<(usize, usize)> {
    let mut unmatched_rust_indices = (0..rust_rows.len()).collect::<Vec<_>>();
    let mut pairings = Vec::with_capacity(rust_rows.len().min(oracle_rows.len()));
    for (oracle_index, oracle_row) in oracle_rows.iter().enumerate() {
        let matching_position = unmatched_rust_indices
            .iter()
            .position(|rust_index| {
                rust_rows[*rust_index]
                    .material_name
                    .eq_ignore_ascii_case(&oracle_row.material_name)
            })
            .or_else(|| (!unmatched_rust_indices.is_empty()).then_some(0));
        let Some(matching_position) = matching_position else {
            break;
        };
        let rust_index = unmatched_rust_indices.remove(matching_position);
        pairings.push((rust_index, oracle_index));
    }
    pairings
}

fn energyplus_window_gas_eio_thickness(thickness_m: f64) -> Option<f64> {
    energyplus_round_sig_digits_positive(thickness_m, 3)
}

fn energyplus_material_details_eio_thickness(thickness_m: f64) -> Option<f64> {
    energyplus_round_sig_digits_positive(thickness_m, 4)
}

fn energyplus_round_sig_digits_positive(value: f64, precision: usize) -> Option<f64> {
    // EnergyPlus IOFiles.hh selects fixed output at this threshold. It nudges
    // positive fixed values up to 100000 by three ULPs and scientific values
    // by one ULP before formatting to retain the legacy RoundSigDigits behavior.
    const FIXED_OUTPUT_THRESHOLD: f64 = f64::from_bits(0x3fb9_9999_9999_9999);
    const MAX_DIGITS_10: i32 = 17;

    if !value.is_finite() || value <= 0.0 || precision > MAX_DIGITS_10 as usize {
        return None;
    }

    let precision_i32 = precision as i32;
    let fixed_output = value >= FIXED_OUTPUT_THRESHOLD;
    let rendered = if fixed_output {
        let output_precision =
            if value > 100_000.0 && value.log10() as i32 + precision_i32 >= MAX_DIGITS_10 {
                0
            } else {
                precision
            };
        let mut adjusted = value;
        if value <= 100_000.0 {
            for _ in 0..3 {
                adjusted = f64::from_bits(adjusted.to_bits() + 1);
            }
        }
        format!("{adjusted:.output_precision$}")
    } else {
        let adjusted = f64::from_bits(value.to_bits() + 1);
        format!("{adjusted:.precision$E}")
    };

    rendered
        .parse::<f64>()
        .ok()
        .filter(|value| value.is_finite() && *value > 0.0)
}

const WINDOW_MATERIAL_GAS_EIO_HEADER: &str =
    "! <WindowMaterial:Gas>,Material Name,GasType,Thickness {m}";

fn window_material_gas_eio_shape(eio_contents: &str) -> (usize, usize) {
    let mut header_rows = 0;
    let mut data_rows = 0;
    for line in eio_contents.lines() {
        if line == WINDOW_MATERIAL_GAS_EIO_HEADER {
            header_rows += 1;
        }
        if line.trim_start().starts_with("WindowMaterial:Gas,") {
            data_rows += 1;
        }
    }
    (header_rows, data_rows)
}

fn normalized_material_name(name: &str) -> String {
    name.trim().to_ascii_uppercase()
}

fn window_material_gas_mixture_oracle_indices(
    rust_rows: &[WindowMaterialGasMixtureRow],
    oracle_rows: &[ep_compare::EioMaterialDetails],
) -> Vec<Vec<usize>> {
    let mut indices_by_name = std::collections::BTreeMap::<String, Vec<usize>>::new();
    for (oracle_index, oracle_row) in oracle_rows.iter().enumerate() {
        indices_by_name
            .entry(normalized_material_name(&oracle_row.material_name))
            .or_default()
            .push(oracle_index);
    }
    rust_rows
        .iter()
        .map(|rust_row| {
            indices_by_name
                .get(&normalized_material_name(&rust_row.material_name))
                .cloned()
                .unwrap_or_default()
        })
        .collect()
}

fn window_material_gas_mixture_numeric_fields(
    rust_row: &WindowMaterialGasMixtureRow,
    oracle_row: &ep_compare::EioMaterialDetails,
) -> [(&'static str, f64, f64); 8] {
    [
        (
            "thickness_m",
            oracle_row.thickness_m,
            energyplus_material_details_eio_thickness(rust_row.fields.thickness_m)
                .unwrap_or(f64::NAN),
        ),
        (
            "thermal_resistance_m2_k_per_w",
            oracle_row.thermal_resistance_m2_k_per_w,
            0.0,
        ),
        (
            "conductivity_w_per_m_k",
            oracle_row.conductivity_w_per_m_k,
            0.0,
        ),
        ("density_kg_per_m3", oracle_row.density_kg_per_m3, 0.0),
        (
            "specific_heat_j_per_kg_k",
            oracle_row.specific_heat_j_per_kg_k,
            0.0,
        ),
        ("thermal_absorptance", oracle_row.thermal_absorptance, 0.0),
        ("solar_absorptance", oracle_row.solar_absorptance, 0.0),
        ("visible_absorptance", oracle_row.visible_absorptance, 0.0),
    ]
}

fn window_material_gas_mixture_row_matches(
    rust_row: &WindowMaterialGasMixtureRow,
    oracle_row: &ep_compare::EioMaterialDetails,
) -> bool {
    oracle_row.material_name == rust_row.material_name
        && oracle_row.roughness == "MediumRough"
        && window_material_gas_mixture_numeric_fields(rust_row, oracle_row)
            .into_iter()
            .all(|(_field, oracle_value, expected_value)| oracle_value == expected_value)
}

fn record_window_material_gas_mixture_divergence(
    first_divergence: &mut Option<String>,
    rust_row: &WindowMaterialGasMixtureRow,
    oracle_row: &ep_compare::EioMaterialDetails,
) {
    let prefix = format!("material {}", rust_row.material_name);
    if oracle_row.material_name != rust_row.material_name {
        record_first_divergence(
            first_divergence,
            format!(
                "{prefix} field material_name expected {} observed {}",
                rust_row.material_name, oracle_row.material_name
            ),
        );
        return;
    }
    if oracle_row.roughness != "MediumRough" {
        record_first_divergence(
            first_divergence,
            format!(
                "{prefix} field roughness expected MediumRough observed {}",
                oracle_row.roughness
            ),
        );
        return;
    }
    if let Some((field, oracle_value, expected_value)) =
        window_material_gas_mixture_numeric_fields(rust_row, oracle_row)
            .into_iter()
            .find(|(_field, oracle_value, expected_value)| oracle_value != expected_value)
    {
        record_first_divergence(
            first_divergence,
            format!(
                "{prefix} field {field} expected {expected_value:.9} observed {oracle_value:.9}"
            ),
        );
    }
}

fn window_material_gas_row_matches(
    rust_row: &WindowMaterialGasRow,
    oracle_row: &ep_compare::EioWindowMaterialGas,
) -> bool {
    oracle_row
        .material_name
        .eq_ignore_ascii_case(&rust_row.material_name)
        && oracle_row.gas_type == window_gas_type_name(rust_row.fields.gas_type)
        && energyplus_window_gas_eio_thickness(rust_row.fields.thickness_m)
            .is_some_and(|value| value == oracle_row.thickness_m)
}

fn record_window_material_gas_divergence(
    first_divergence: &mut Option<String>,
    rust_row: &WindowMaterialGasRow,
    oracle_row: &ep_compare::EioWindowMaterialGas,
    occurrence_index: usize,
) {
    let prefix = format!(
        "occurrence {} construction {} material {}",
        occurrence_index + 1,
        rust_row.construction_name,
        rust_row.material_name
    );
    if !oracle_row
        .material_name
        .eq_ignore_ascii_case(&rust_row.material_name)
    {
        record_first_divergence(
            first_divergence,
            format!(
                "{prefix} field material_name expected {} observed {}",
                oracle_row.material_name, rust_row.material_name
            ),
        );
        return;
    }

    let rust_gas_type = window_gas_type_name(rust_row.fields.gas_type);
    if oracle_row.gas_type != rust_gas_type {
        record_first_divergence(
            first_divergence,
            format!(
                "{prefix} field gas_type expected {} observed {}",
                oracle_row.gas_type, rust_gas_type
            ),
        );
        return;
    }

    let formatted_rust_thickness = energyplus_window_gas_eio_thickness(rust_row.fields.thickness_m);
    if formatted_rust_thickness != Some(oracle_row.thickness_m) {
        record_first_divergence(
            first_divergence,
            format!(
                "{prefix} field thickness_m expected {:.9} observed input {:.9} EnergyPlus .3R {:?}",
                oracle_row.thickness_m, rust_row.fields.thickness_m, formatted_rust_thickness
            ),
        );
    }
}

fn window_material_gap_equivalent_layer_row_matches(
    rust_row: &WindowMaterialGapEquivalentLayerRow,
    oracle_row: &ep_compare::EioWindowMaterialGapEquivalentLayer,
) -> bool {
    oracle_row
        .material_name
        .eq_ignore_ascii_case(&rust_row.material_name)
        && oracle_row.gas_type == rust_row.fields.gas_type.energyplus_name()
        && energyplus_window_gas_eio_thickness(rust_row.fields.thickness_m)
            == Some(oracle_row.gap_thickness_m)
        && oracle_row.gap_vent_type == rust_row.fields.gap_vent_type.energyplus_name()
}

fn record_window_material_gap_equivalent_layer_divergence(
    first_divergence: &mut Option<String>,
    rust_row: &WindowMaterialGapEquivalentLayerRow,
    oracle_row: &ep_compare::EioWindowMaterialGapEquivalentLayer,
    occurrence_index: usize,
) {
    let prefix = format!(
        "occurrence {} construction {} layer {} material {}",
        occurrence_index + 1,
        rust_row.construction_name,
        rust_row.layer_number,
        rust_row.material_name
    );
    if !oracle_row
        .material_name
        .eq_ignore_ascii_case(&rust_row.material_name)
    {
        record_first_divergence(
            first_divergence,
            format!(
                "{prefix} field material_name expected {} observed {}",
                oracle_row.material_name, rust_row.material_name
            ),
        );
        return;
    }

    let rust_gas_type = rust_row.fields.gas_type.energyplus_name();
    if oracle_row.gas_type != rust_gas_type {
        record_first_divergence(
            first_divergence,
            format!(
                "{prefix} field gas_type expected {} observed {}",
                oracle_row.gas_type, rust_gas_type
            ),
        );
        return;
    }

    let formatted_rust_thickness = energyplus_window_gas_eio_thickness(rust_row.fields.thickness_m);
    if formatted_rust_thickness != Some(oracle_row.gap_thickness_m) {
        record_first_divergence(
            first_divergence,
            format!(
                "{prefix} field gap_thickness_m expected {:.9} observed input {:.9} EnergyPlus .3R {:?}",
                oracle_row.gap_thickness_m, rust_row.fields.thickness_m, formatted_rust_thickness
            ),
        );
        return;
    }

    let rust_gap_vent_type = rust_row.fields.gap_vent_type.energyplus_name();
    if oracle_row.gap_vent_type != rust_gap_vent_type {
        record_first_divergence(
            first_divergence,
            format!(
                "{prefix} field gap_vent_type expected {} observed {}",
                oracle_row.gap_vent_type, rust_gap_vent_type
            ),
        );
    }
}

fn equivalent_layer_eio_auto_value(value: AutoOrNumber) -> f64 {
    match value {
        AutoOrNumber::AutoCalculate => -99_999.0,
        AutoOrNumber::Value(value) => value,
    }
}

fn auto_or_number_display(value: AutoOrNumber) -> String {
    match value {
        AutoOrNumber::AutoCalculate => "Autocalculate".to_string(),
        AutoOrNumber::Value(value) => format!("{value:.6}"),
    }
}

fn window_glazing_equivalent_layer_numeric_fields(
    rust_row: &WindowGlazingEquivalentLayerRow,
    oracle_row: &ep_compare::EioWindowMaterialGlazingEquivalentLayer,
) -> [(&'static str, f64, f64); 14] {
    [
        (
            "front_beam_beam_solar_transmittance",
            oracle_row.front_beam_beam_solar_transmittance,
            rust_row.fields.solar.beam_beam.front_transmittance,
        ),
        (
            "back_beam_beam_solar_transmittance",
            oracle_row.back_beam_beam_solar_transmittance,
            rust_row.fields.solar.beam_beam.back_transmittance,
        ),
        (
            "front_beam_beam_solar_reflectance",
            oracle_row.front_beam_beam_solar_reflectance,
            rust_row.fields.solar.beam_beam.front_reflectance,
        ),
        (
            "back_beam_beam_solar_reflectance",
            oracle_row.back_beam_beam_solar_reflectance,
            rust_row.fields.solar.beam_beam.back_reflectance,
        ),
        (
            "front_beam_diffuse_solar_transmittance",
            oracle_row.front_beam_diffuse_solar_transmittance,
            rust_row.fields.solar.beam_diffuse.front_transmittance,
        ),
        (
            "back_beam_diffuse_solar_transmittance",
            oracle_row.back_beam_diffuse_solar_transmittance,
            rust_row.fields.solar.beam_diffuse.back_transmittance,
        ),
        (
            "front_beam_diffuse_solar_reflectance",
            oracle_row.front_beam_diffuse_solar_reflectance,
            rust_row.fields.solar.beam_diffuse.front_reflectance,
        ),
        (
            "back_beam_diffuse_solar_reflectance",
            oracle_row.back_beam_diffuse_solar_reflectance,
            rust_row.fields.solar.beam_diffuse.back_reflectance,
        ),
        (
            "diffuse_diffuse_solar_transmittance",
            oracle_row.diffuse_diffuse_solar_transmittance,
            equivalent_layer_eio_auto_value(rust_row.fields.solar.diffuse_diffuse.transmittance),
        ),
        (
            "front_diffuse_diffuse_solar_reflectance",
            oracle_row.front_diffuse_diffuse_solar_reflectance,
            equivalent_layer_eio_auto_value(
                rust_row.fields.solar.diffuse_diffuse.front_reflectance,
            ),
        ),
        (
            "back_diffuse_diffuse_solar_reflectance",
            oracle_row.back_diffuse_diffuse_solar_reflectance,
            equivalent_layer_eio_auto_value(rust_row.fields.solar.diffuse_diffuse.back_reflectance),
        ),
        (
            "infrared_transmittance",
            oracle_row.infrared_transmittance,
            rust_row.fields.infrared_transmittance,
        ),
        (
            "front_infrared_emissivity",
            oracle_row.front_infrared_emissivity,
            rust_row.fields.front_infrared_emissivity,
        ),
        (
            "back_infrared_emissivity",
            oracle_row.back_infrared_emissivity,
            rust_row.fields.back_infrared_emissivity,
        ),
    ]
}

fn window_glazing_equivalent_layer_row_matches(
    rust_row: &WindowGlazingEquivalentLayerRow,
    oracle_row: &ep_compare::EioWindowMaterialGlazingEquivalentLayer,
    tolerance: Tolerance,
) -> bool {
    oracle_row
        .material_name
        .eq_ignore_ascii_case(&rust_row.material_name)
        && oracle_row
            .optical_data_type
            .eq_ignore_ascii_case("SpectralAverage")
        && oracle_row.spectral_data_set_name.is_none()
        && window_glazing_equivalent_layer_numeric_fields(rust_row, oracle_row)
            .into_iter()
            .all(|(_field, expected, observed)| tolerance.accepts(expected, observed))
}

fn window_glazing_equivalent_layer_pairings(
    rust_rows: &[WindowGlazingEquivalentLayerRow],
    oracle_rows: &[ep_compare::EioWindowMaterialGlazingEquivalentLayer],
) -> Vec<(usize, usize)> {
    oracle_rows
        .iter()
        .enumerate()
        .filter_map(|(oracle_index, oracle_row)| {
            rust_rows
                .iter()
                .position(|rust_row| {
                    rust_row
                        .material_name
                        .eq_ignore_ascii_case(&oracle_row.material_name)
                })
                .map(|rust_index| (rust_index, oracle_index))
        })
        .collect()
}

fn record_window_glazing_equivalent_layer_divergence(
    first_divergence: &mut Option<String>,
    rust_row: &WindowGlazingEquivalentLayerRow,
    oracle_row: &ep_compare::EioWindowMaterialGlazingEquivalentLayer,
    tolerance: Tolerance,
    occurrence_index: usize,
) {
    let prefix = format!(
        "oracle occurrence {} material {}",
        occurrence_index + 1,
        rust_row.material_name
    );
    if !oracle_row
        .material_name
        .eq_ignore_ascii_case(&rust_row.material_name)
    {
        record_first_divergence(
            first_divergence,
            format!(
                "{prefix} field material_name expected {} observed {}",
                oracle_row.material_name, rust_row.material_name
            ),
        );
        return;
    }
    if !oracle_row
        .optical_data_type
        .eq_ignore_ascii_case("SpectralAverage")
    {
        record_first_divergence(
            first_divergence,
            format!(
                "{prefix} field optical_data_type expected {} observed SpectralAverage",
                oracle_row.optical_data_type
            ),
        );
        return;
    }
    if oracle_row.spectral_data_set_name.is_some() {
        record_first_divergence(
            first_divergence,
            format!(
                "{prefix} field spectral_data_set_name expected {:?} observed None",
                oracle_row.spectral_data_set_name
            ),
        );
        return;
    }

    for (field, expected, observed) in
        window_glazing_equivalent_layer_numeric_fields(rust_row, oracle_row)
    {
        if !tolerance.accepts(expected, observed) {
            record_first_divergence(
                first_divergence,
                format!("{prefix} field {field} expected {expected:.6} observed {observed:.6}"),
            );
            return;
        }
    }
}

fn window_glazing_spectral_average_row_matches(
    rust_row: &WindowGlazingSpectralAverageRow,
    oracle_row: &ep_compare::EioWindowMaterialGlazing,
    tolerance: Tolerance,
) -> bool {
    oracle_row
        .material_name
        .eq_ignore_ascii_case(&rust_row.material_name)
        && oracle_row
            .optical_data_type
            .eq_ignore_ascii_case("SpectralAverage")
        && oracle_row.spectral_data_set_name.is_none()
        && tolerance.accepts(oracle_row.thickness_m, rust_row.fields.thickness_m)
        && tolerance.accepts(
            oracle_row.solar_transmittance,
            rust_row.fields.solar_transmittance_at_normal_incidence,
        )
        && tolerance.accepts(
            oracle_row.front_solar_reflectance,
            rust_row
                .fields
                .front_side_solar_reflectance_at_normal_incidence,
        )
        && tolerance.accepts(
            oracle_row.back_solar_reflectance,
            rust_row
                .fields
                .back_side_solar_reflectance_at_normal_incidence,
        )
        && tolerance.accepts(
            oracle_row.visible_transmittance,
            rust_row.fields.visible_transmittance_at_normal_incidence,
        )
        && tolerance.accepts(
            oracle_row.front_visible_reflectance,
            rust_row
                .fields
                .front_side_visible_reflectance_at_normal_incidence,
        )
        && tolerance.accepts(
            oracle_row.back_visible_reflectance,
            rust_row
                .fields
                .back_side_visible_reflectance_at_normal_incidence,
        )
        && tolerance.accepts(
            oracle_row.infrared_transmittance,
            rust_row.fields.infrared_transmittance_at_normal_incidence,
        )
        && tolerance.accepts(
            oracle_row.front_thermal_emissivity,
            rust_row.fields.front_side_infrared_hemispherical_emissivity,
        )
        && tolerance.accepts(
            oracle_row.back_thermal_emissivity,
            rust_row.fields.back_side_infrared_hemispherical_emissivity,
        )
        && tolerance.accepts(
            oracle_row.conductivity_w_per_m_k,
            rust_row.fields.conductivity_w_per_m_k,
        )
        && tolerance.accepts(
            oracle_row.dirt_factor,
            rust_row
                .fields
                .dirt_correction_factor_for_solar_and_visible_transmittance,
        )
        && oracle_row.solar_diffusing == rust_row.fields.solar_diffusing
}

fn window_glazing_spectral_average_pairings(
    rust_rows: &[WindowGlazingSpectralAverageRow],
    oracle_rows: &[ep_compare::EioWindowMaterialGlazing],
) -> Vec<(usize, usize)> {
    let rust_material_names = rust_rows
        .iter()
        .map(|row| row.material_name.as_str())
        .collect::<Vec<_>>();
    window_glazing_material_name_occurrence_pairings(&rust_material_names, oracle_rows)
}

fn select_eio_window_material_glazing_occurrences(
    oracle_rows: Vec<ep_compare::EioWindowMaterialGlazing>,
    local_material_names: &[&str],
) -> Vec<ep_compare::EioWindowMaterialGlazing> {
    oracle_rows
        .into_iter()
        .filter(|oracle_row| {
            local_material_names
                .iter()
                .any(|name| name.eq_ignore_ascii_case(&oracle_row.material_name))
        })
        .collect()
}

fn window_glazing_material_name_occurrence_pairings(
    rust_material_names: &[&str],
    oracle_rows: &[ep_compare::EioWindowMaterialGlazing],
) -> Vec<(usize, usize)> {
    let mut unmatched_rust_indices = (0..rust_material_names.len()).collect::<Vec<_>>();
    let mut pairings = Vec::with_capacity(rust_material_names.len().min(oracle_rows.len()));
    for (oracle_index, oracle_row) in oracle_rows.iter().enumerate() {
        let matching_position = unmatched_rust_indices
            .iter()
            .position(|rust_index| {
                rust_material_names[*rust_index].eq_ignore_ascii_case(&oracle_row.material_name)
            })
            .or_else(|| (!unmatched_rust_indices.is_empty()).then_some(0));
        let Some(matching_position) = matching_position else {
            break;
        };
        let rust_index = unmatched_rust_indices.remove(matching_position);
        pairings.push((rust_index, oracle_index));
    }

    pairings
}

fn record_window_glazing_spectral_average_divergence(
    first_divergence: &mut Option<String>,
    rust_row: &WindowGlazingSpectralAverageRow,
    oracle_row: &ep_compare::EioWindowMaterialGlazing,
    tolerance: Tolerance,
    occurrence_index: usize,
) {
    let prefix = format!(
        "occurrence {} construction {} material {}",
        occurrence_index + 1,
        rust_row.construction_name,
        rust_row.material_name
    );
    if !oracle_row
        .material_name
        .eq_ignore_ascii_case(&rust_row.material_name)
    {
        record_first_divergence(
            first_divergence,
            format!(
                "{prefix} field material_name expected {} observed {}",
                oracle_row.material_name, rust_row.material_name
            ),
        );
        return;
    }
    if !oracle_row
        .optical_data_type
        .eq_ignore_ascii_case("SpectralAverage")
    {
        record_first_divergence(
            first_divergence,
            format!(
                "{prefix} field optical_data_type expected {} observed SpectralAverage",
                oracle_row.optical_data_type
            ),
        );
        return;
    }
    if oracle_row.spectral_data_set_name.is_some() {
        record_first_divergence(
            first_divergence,
            format!(
                "{prefix} field spectral_data_set_name expected {:?} observed None",
                oracle_row.spectral_data_set_name
            ),
        );
        return;
    }

    let numeric_fields = [
        (
            "thickness_m",
            oracle_row.thickness_m,
            rust_row.fields.thickness_m,
        ),
        (
            "solar_transmittance",
            oracle_row.solar_transmittance,
            rust_row.fields.solar_transmittance_at_normal_incidence,
        ),
        (
            "front_solar_reflectance",
            oracle_row.front_solar_reflectance,
            rust_row
                .fields
                .front_side_solar_reflectance_at_normal_incidence,
        ),
        (
            "back_solar_reflectance",
            oracle_row.back_solar_reflectance,
            rust_row
                .fields
                .back_side_solar_reflectance_at_normal_incidence,
        ),
        (
            "visible_transmittance",
            oracle_row.visible_transmittance,
            rust_row.fields.visible_transmittance_at_normal_incidence,
        ),
        (
            "front_visible_reflectance",
            oracle_row.front_visible_reflectance,
            rust_row
                .fields
                .front_side_visible_reflectance_at_normal_incidence,
        ),
        (
            "back_visible_reflectance",
            oracle_row.back_visible_reflectance,
            rust_row
                .fields
                .back_side_visible_reflectance_at_normal_incidence,
        ),
        (
            "infrared_transmittance",
            oracle_row.infrared_transmittance,
            rust_row.fields.infrared_transmittance_at_normal_incidence,
        ),
        (
            "front_thermal_emissivity",
            oracle_row.front_thermal_emissivity,
            rust_row.fields.front_side_infrared_hemispherical_emissivity,
        ),
        (
            "back_thermal_emissivity",
            oracle_row.back_thermal_emissivity,
            rust_row.fields.back_side_infrared_hemispherical_emissivity,
        ),
        (
            "conductivity_w_per_m_k",
            oracle_row.conductivity_w_per_m_k,
            rust_row.fields.conductivity_w_per_m_k,
        ),
        (
            "dirt_factor",
            oracle_row.dirt_factor,
            rust_row
                .fields
                .dirt_correction_factor_for_solar_and_visible_transmittance,
        ),
    ];
    for (field, expected, observed) in numeric_fields {
        if !tolerance.accepts(expected, observed) {
            record_first_divergence(
                first_divergence,
                format!("{prefix} field {field} expected {expected:.6} observed {observed:.6}"),
            );
            return;
        }
    }
    if oracle_row.solar_diffusing != rust_row.fields.solar_diffusing {
        record_first_divergence(
            first_divergence,
            format!(
                "{prefix} field solar_diffusing expected {} observed {}",
                yes_no(oracle_row.solar_diffusing),
                yes_no(rust_row.fields.solar_diffusing)
            ),
        );
    }
}

fn window_glazing_refraction_extinction_row_matches(
    rust_row: &WindowGlazingRefractionExtinctionRow,
    oracle_row: &ep_compare::EioWindowMaterialGlazing,
    tolerance: Tolerance,
) -> bool {
    let optical = rust_row.fields.normal_incidence_optical_properties();
    oracle_row
        .material_name
        .eq_ignore_ascii_case(&rust_row.material_name)
        && oracle_row
            .optical_data_type
            .eq_ignore_ascii_case("SpectralAverage")
        && oracle_row.spectral_data_set_name.is_none()
        && tolerance.accepts(oracle_row.thickness_m, rust_row.fields.thickness_m)
        && tolerance.accepts(
            oracle_row.solar_transmittance,
            optical.solar_transmittance_at_normal_incidence,
        )
        && tolerance.accepts(
            oracle_row.front_solar_reflectance,
            optical.front_side_solar_reflectance_at_normal_incidence,
        )
        && tolerance.accepts(
            oracle_row.back_solar_reflectance,
            optical.back_side_solar_reflectance_at_normal_incidence,
        )
        && tolerance.accepts(
            oracle_row.visible_transmittance,
            optical.visible_transmittance_at_normal_incidence,
        )
        && tolerance.accepts(
            oracle_row.front_visible_reflectance,
            optical.front_side_visible_reflectance_at_normal_incidence,
        )
        // EnergyPlus 26.1 emits its solar-front value in the visible-back field
        // for this input method; the typed optical projection preserves that quirk.
        && tolerance.accepts(
            oracle_row.back_visible_reflectance,
            optical.back_side_visible_reflectance_at_normal_incidence,
        )
        && tolerance.accepts(
            oracle_row.infrared_transmittance,
            rust_row.fields.infrared_transmittance_at_normal_incidence,
        )
        && tolerance.accepts(
            oracle_row.front_thermal_emissivity,
            rust_row.fields.infrared_hemispherical_emissivity,
        )
        && tolerance.accepts(
            oracle_row.back_thermal_emissivity,
            rust_row.fields.infrared_hemispherical_emissivity,
        )
        && tolerance.accepts(
            oracle_row.conductivity_w_per_m_k,
            rust_row.fields.conductivity_w_per_m_k,
        )
        && tolerance.accepts(
            oracle_row.dirt_factor,
            rust_row
                .fields
                .dirt_correction_factor_for_solar_and_visible_transmittance,
        )
        && oracle_row.solar_diffusing == rust_row.fields.solar_diffusing
}

fn window_glazing_refraction_extinction_pairings(
    rust_rows: &[WindowGlazingRefractionExtinctionRow],
    oracle_rows: &[ep_compare::EioWindowMaterialGlazing],
) -> Vec<(usize, usize)> {
    let rust_material_names = rust_rows
        .iter()
        .map(|row| row.material_name.as_str())
        .collect::<Vec<_>>();
    window_glazing_material_name_occurrence_pairings(&rust_material_names, oracle_rows)
}

